function navigate(page,options={}){
 const current=state.page;
 if(!options.replace&&!options.fromBack&&current&&current!==page&&$(`#page-${current}`)?.classList.contains('active')){
  state.pageHistory.push(current);
  if(state.pageHistory.length>30)state.pageHistory.shift();
 }
 const targetPageId=`page-${page}`;
 state.page=page;
 $$('.page').forEach(p=>{
  const active=p.id===targetPageId;
  p.classList.toggle('active',active);
  p.hidden=!active;
  p.setAttribute('aria-hidden',active?'false':'true');
 });
 $$('.nav-item[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));
 $('#sidebar').classList.remove('open');
 const content=$('.content');
 if(content){content.scrollTop=0;content.scrollLeft=0}
 window.scrollTo?.(0,0);
 requestAnimationFrame(()=>{
  if(page==='formalChart')renderChart('formal',state.formalPage);
  if(page==='nonChart')renderChart('non',state.nonPage);
  if(page==='people')renderPeople();
  if(page==='statusChart')renderStatusChart();
  if(page==='personnelDirectory'){if(!state.statusCatalog.length)buildStatusCatalog();fillPersonnelDirectoryScopes();renderPersonnelDirectory()}
  if(page==='personnelEducation')renderPersonnelEducation();
  if(page==='reports'){if(!state.statusCatalog.length)buildStatusCatalog();fillReportUnits();renderReports()}
  if(page==='history')renderHistory();
 });
}
function goBackPage(){
 const previous=state.pageHistory.pop();
 navigate(previous||'formalChart',{fromBack:true});
}
