function routeNorm(v){return norm(v).replace(/\s/g,'')}
function routeTarget(page,text){
 const entries=Object.entries(CHART_ROUTES[page]||{});const k=routeNorm(text);
 const hit=entries.find(([t])=>routeNorm(t)===k)||entries.find(([t])=>routeNorm(t).includes(k)||k.includes(routeNorm(t)));
 if(hit)return +hit[1];
 const exact=state.slides.filter(s=>s.page!==page&&routeNorm(s.title)===k);
 return exact.length===1?exact[0].page:0;
}
