 const dock=document.createElement('button');dock.type='button';dock.className='page-one-hold-dock';
 dock.innerHTML=`<span>↝</span><div><b>حفظ پست‌های صفحه نخست</b><small>${fa(entries.length)} نفر — نمایش جداگانه</small></div>`;
