function editInput(n,l,v){return`<label>${l}<input name="${n}" value="${esc(v||'')}"></label>`}function editSelect(n,l,opts,v){return`<label>${l}<select name="${n}">${opts.map(o=>`<option ${o===v?'selected':''}>${o}</option>`).join('')}</select></label>`}
async function savePerson(e,id){e.preventDefault();if(!org421Can(ORG421_ACCESS.keys.editData))return toast('دسترسی محدود','حساب شما مجوز ذخیره تغییرات را ندارد.','error');const fd=new FormData(e.target),obj=Object.fromEntries(fd.entries());obj.full_name=`${obj.name} ${obj.last_name}`.trim();try{let saved;if(state.server)saved=await api.post('/person/save',{id,...obj});else{if(id){const i=state.people.findIndex(x=>x.id===id);const old={...state.people[i]};state.people[i]={...old,...obj};saved=state.people[i];recordLocalHistory('ویرایش دستی',saved.full_name)}else{saved={...obj,id:'M-'+Date.now(),source:'manual',named_post:false};state.people.push(saved);recordLocalHistory('افزودن دستی',saved.full_name)}await persistStandalone()}if(state.server){const d=await api.get('/bootstrap');hydrate(d)}else{indexPeople();resetDerivedCaches()}$('#personModal').classList.add('hidden');if($('#kpiGrid'))renderDashboard();if($('#peopleTableWrap'))renderPeople();await captureStatusSnapshot('ویرایش دستی');toast('اطلاعات ذخیره شد',obj.full_name)}catch(err){toast('ذخیره انجام نشد',err.message,'error')}}

