 $('#cancelImport').onclick=()=>box.innerHTML='<div class="empty-state"><div>⇧</div><h3>فرآیند لغو شد</h3><p>هیچ تغییری روی داده‌های اصلی اعمال نشد.</p></div>';
 if(j.can_apply)$('#applyImport').onclick=applyImport;
