 state.summary={...state.summary,formal_count:state.people.filter(p=>p.source==='formal'||p.employment_group==='رسمی').length,nonofficial_count:state.people.filter(p=>p.source!=='formal'&&p.employment_group!=='رسمی').length,total_count:state.people.length,named_count:state.people.filter(p=>p.named_post).length,hold_count:state.people.filter(p=>p.is_hold_position).length,outside_chart_count:state.people.filter(p=>p.outside_chart).length,formal_outside_count:state.people.filter(p=>p.source==='formal'&&p.outside_chart).length,nonofficial_groups:groups};
