 if(!arr.length){host.innerHTML=genericPeopleTable(arr);return}
 host.innerHTML=`<div class="directory-progress-note" aria-live="polite"><span>نمایش ${fa(arr.length)} نفر</span><small>در حال آماده‌سازی ردیف‌ها…</small></div><table><thead><tr><th>نام</th><th>شماره پرسنلی</th><th>نوع همکاری</th><th>پست</th><th>واحد مصوب</th><th>محل واقعی</th><th>حوزه فعالیت</th><th>وضعیت ویژه</th></tr></thead><tbody></tbody></table>`;
 const body=host.querySelector('tbody'),note=host.querySelector('.directory-progress-note small');let index=0;const chunk=100;
