 const append=()=>{if(host._directoryRenderToken!==token)return;const end=Math.min(arr.length,index+chunk),html=[];for(;index<end;index++)html.push(directoryPersonRow(arr[index]));body.insertAdjacentHTML('beforeend',html.join(''));if(index<arr.length){if(note)note.textContent=`${fa(index)} ردیف آماده شده است…`;idleRun(append)}else{if(note)note.textContent='همه ردیف‌ها آماده‌اند.';host.classList.add('directory-render-complete')}};
