function downloadProfessionalXlsx(config){
 try{const rows=config.rows||[];const bytes=professionalWorkbookBytes(config);if(bytes.byteLength<1800)throw new Error('ساخت فایل Excel کامل نشد.');const blob=new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});downloadBlob(blob,safeFileName(config.filename||config.title||'گزارش').replace(/\.xlsx$/i,'')+'.xlsx');toast('خروجی Excel آماده شد',`${fa(rows.length)} ردیف در دو شیت «گزارش» و «داده خام»`)}catch(e){console.error(e);toast('خروجی Excel ساخته نشد',e.message||String(e),'error')}
}
function exportPeople(arr,options={}){
 const groups={};arr.forEach(p=>groups[p.employment_group]=(groups[p.employment_group]||0)+1);
 const columns=[['ردیف',8],['شماره پرسنلی',15],['نام',16],['نام خانوادگی',22],['نوع همکاری',15],['نوع همکاری تفصیلی',22],['عنوان پست',34],['کد پست',14],['واحد سازمانی مصوب',34],['محل خدمت واقعی',30],['حوزه فعالیت',30],['وضعیت اشتغال',16],['شرکت پیمانکار',26],['وضعیت جانمایی',28],['اطمینان جانمایی',16],['پست با نام',16],['حفظ پست',12],['خارج از چارت',14]];
 const rows=arr.map((p,i)=>[i+1,p.personnel_no,p.name,p.last_name,p.employment_group,p.employment_subtype,p.position_title,p.position_code,p.organizational_unit,p.actual_location,p.activity_area,p.status,p.company||'',p.placement_status||'',p.placement_confidence?Math.round(Number(p.placement_confidence)*100):'',p.named_post?(p.named_post_type||'بله'):'',p.is_hold_position?'بله':'',p.outside_chart?'بله':'']);
 const summary=[['تعداد کل',arr.length],...Object.entries(groups)];
 const scope=options.scope||'بر اساس فیلتر انتخاب‌شده',group=options.group||'همه انواع همکاری',title=options.title||'گزارش منابع انسانی';
 downloadProfessionalXlsx({title,subtitle:`حوزه: ${scope}  |  نوع همکاری: ${group}`,sheetName:'فهرست پرسنل',columns,rows,summary,filename:options.filename||`${title}-${scope}.xlsx`})
}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.style.display='none';a.rel='noopener';document.body.appendChild(a);requestAnimationFrame(()=>a.click());setTimeout(()=>{a.remove();URL.revokeObjectURL(url)},60000)}

