/* v4.0.29 — real unified renderer: merge matching nonofficial nodes into the same organization node */
function unifiedChartMerge(){
 const cache=state._cache.unifiedChartMerge;if(cache)return cache;
 const hiddenSourceIds=new Set(),sourceToTarget=new Map(),targetPeople=new Map();
 const isSyntheticNon=n=>!!(n&&n.synthetic_nonofficial_audit);
 const isMergeTarget=n=>!!n&&!isSyntheticNon(n)&&!n.synthetic_nonofficial_hold&&!n.synthetic_nonofficial_outside&&!n.synthetic_formal_hold&&!n.synthetic_formal_outside&&!n.hold_position_node&&!n.outside_chart_node;
 const center=n=>({x:(+n.x||0)+(+n.w||0)/2,y:(+n.y||0)+(+n.h||0)/2});
 (state.slides||[]).forEach(slide=>{
  const targets=(slide.nodes||[]).filter(isMergeTarget);
  const byText=new Map();
  targets.forEach(t=>{const k=norm(t.text);if(!byText.has(k))byText.set(k,[]);byText.get(k).push(t)});
  (slide.nodes||[]).filter(isSyntheticNon).forEach(src=>{
   const people=src.nonofficial_people||[];if(!people.length)return;
   const list=byText.get(norm(src.text))||[];if(!list.length)return;
   const c=center(src);
   const target=list.map(t=>({t,d:Math.hypot(center(t).x-c.x,center(t).y-c.y)})).sort((a,b)=>a.d-b.d)[0].t;
   hiddenSourceIds.add(src.id);sourceToTarget.set(src.id,target.id);
   if(!targetPeople.has(target.id))targetPeople.set(target.id,[]);
   targetPeople.get(target.id).push(...people);
  });
 });
 const out={hiddenSourceIds,sourceToTarget,targetPeople,mergedNodes:hiddenSourceIds.size,mergedPeople:[...targetPeople.values()].reduce((s,a)=>s+a.length,0)};
 state._cache.unifiedChartMerge=out;return out;
}
