 const units=structural.filter(org41UnitNode);
 const rootGuess=units.slice().sort((a,b)=>org41OriginalCenter(a).y-org41OriginalCenter(b).y||org41OriginalCenter(a).x-org41OriginalCenter(b).x)[0]||structural.slice().sort((a,b)=>org41OriginalCenter(a).y-org41OriginalCenter(b).y)[0];
