 const above=(u,n)=>org41OriginalCenter(u).y < org41OriginalCenter(n).y-.7;
 function bestCandidate(n,onlyScoped=true){
  const nc=org41OriginalCenter(n);
  let candidates=unitScopes.filter(x=>x.u.id!==n.id&&above(x.u,n));
  if(onlyScoped)candidates=candidates.filter(x=>x.set.has(n.id));
  if(!candidates.length)return null;
  const scored=candidates.map(x=>{
   const dx=Math.abs(x.oc.x-nc.x),dy=Math.max(0,nc.y-x.oc.y);
   const sameBand=dx<=Math.max(8,(+x.u.w||12)*.85)?-18:0;
   const unitBonus=org41UnitNode(n)?0:((x.u.scope_node_ids||[]).length?0:18);
   return {u:x.u,score:dx*2.1+dy*.55+x.size*.035+unitBonus+sameBand};
  }).sort((a,b)=>a.score-b.score||org41OriginalCenter(b.u).y-org41OriginalCenter(a.u).y);
  return scored[0]?.u||null;
 }
