  renderBreadcrumb(type,page,slide);renderChartMeta(type,slide,pp);ensureChartControls(type);renderChartCornerLegend(type);
  const sourceBtn=(canvas.closest('.chart-stage')||document).querySelector?.('.chart-view-controls [data-act="source"]');if(sourceBtn)sourceBtn.classList.add('active');
