 const cr=canvas.getBoundingClientRect();let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity;
 [...canvas.querySelectorAll('.org66-ppt-bg,.org66-status-stack,.org66-status-card,.chart-node,.node-floating-flags')].forEach(el=>{const r=el.getBoundingClientRect();if(r.width<1||r.height<1)return;minX=Math.min(minX,r.left-cr.left);minY=Math.min(minY,r.top-cr.top);maxX=Math.max(maxX,r.right-cr.left);maxY=Math.max(maxY,r.bottom-cr.top)});
