  const nodes=(tree.skeletons||[]).slice();
  const count=nodes.length,base=org67CardBase(count);
  if(!nodes.length)return {positions:new Map(),width:ORG67_DEFAULT_W,height:900,base};
  const nat=new Map(nodes.map(n=>[n.id,org67Natural(n)]));
  let minX=Infinity,maxX=-Infinity,minY=Infinity,maxY=-Infinity;
  nodes.forEach(n=>{const r=nat.get(n.id);minX=Math.min(minX,r.cx);maxX=Math.max(maxX,r.cx);minY=Math.min(minY,r.cy);maxY=Math.max(maxY,r.cy)});
