/* v4.0.75 — HR status-chart exception
   فیروزه احمدی (شماره پرسنلی 2074 / F-2074) در محاسبه «وضعیت چارت»
   برای معاونت منابع انسانی و زیرحوزه‌های همان صفحه وارد نمی‌شود.
   داده پرسنلی و لیست کلی پرسنل دست‌نخورده می‌ماند. */
const org75PreviousStatusPeopleForScope=statusPeopleForScope;
function org75IsHrStatusScope(key){
  key=String(key||state.statusScope||'company');
  if(key==='slide:16'||key==='direct:slide:16')return true;
  if(key.startsWith('node:')){
    const n=state.nodeById&&state.nodeById.get(key.slice(5));
    return !!(n&&+n.page===16);
  }
  return false;
}
function org75IsFiroozehAhmadi(p){
  return !!p&&(String(p.id)==='F-2074'||String(p.personnel_no||'')==='2074'||norm(p.full_name||'')===norm('فیروزه احمدی')||norm(p.full_name||'')===norm('فيروزه احمدي'));
}
statusPeopleForScope=function(key='company'){
  key=key||'company';
  const hr=org75IsHrStatusScope(key);
  const cache=state._cache.statusPeople;
  const cacheKey=hr?String(key)+'::exclude-f2074-v75':String(key);
  if(cache?.has(cacheKey))return cache.get(cacheKey);
  let arr=state.people.filter(p=>statusActivityScopeMatch(p,key));
  if(hr)arr=arr.filter(p=>!org75IsFiroozehAhmadi(p));
  cache?.set(cacheKey,arr);
  return arr;
};



