const org82PreviousRenderStatusTable=renderStatusTable;
renderStatusTable=function(children){
  const host=$('#statusTable');
  if(!children.length){org82PreviousRenderStatusTable(children);return;}
  host.dataset.rows=JSON.stringify(children.map(x=>({label:x.label,...x.metrics})));
  host.innerHTML=`<table><thead><tr><th>واحد</th><th>ظرفیت مصوب</th><th>نیروی فعلی</th><th>پوشش</th><th>پست خالی</th><th>درصد خالی</th><th>زن</th><th>مرد</th><th>رسمی</th><th>حفظ پست</th><th>شرکتی</th><th>حجمی</th><th>مشاور</th><th>پست با نام</th><th>خارج چارت</th><th>مازاد</th><th>وضعیت فعلی</th></tr></thead><tbody>${children.map(x=>{const m=x.metrics,status=m.operationalSurplus?`مازاد ${fa(m.operationalSurplus)}`:m.emptyPosts?`${fa(m.emptyPosts)} پست خالی`:'متعادل',cl=m.operationalSurplus?'surplus':m.emptyPosts?'shortage':'balanced';return`<tr data-status-scope="${x.key}"><td><b>${esc(x.label)}</b></td><td>${fa(m.approved)}</td><td>${fa(m.operational)}</td><td><b>${fa(m.currentPercent)}٪</b></td><td><b>${fa(m.emptyPosts)}</b></td><td>${fa(m.emptyPercent)}٪</td><td>${fa(m.female)}</td><td>${fa(m.male)}</td><td>${fa(m.breakdownFormal)}</td><td>${fa(m.breakdownHold)}</td><td>${fa(m.breakdownCompany)}</td><td>${fa(m.breakdownVolume)}</td><td>${fa(m.breakdownConsultant)}</td><td>${fa(m.breakdownNamed)}</td><td>${fa(m.breakdownOutside)}</td><td>${fa(m.operationalSurplus)}</td><td><span class="status-result ${cl}">${status}</span></td></tr>`}).join('')}</tbody></table>`;
  host.querySelectorAll('[data-status-scope]').forEach(r=>r.onclick=()=>openStatusScope(r.dataset.statusScope));
};

exportStatusTable=function(){
  const direct=statusDirectChildren().map(x=>({...x,metrics:statusMetrics(x.key)}));
  const rows=direct.map(x=>({label:x.label,...x.metrics}));
  if(!rows.length){const m=statusMetrics();rows.push({label:scopeLabel(state.statusScope),...m});}
  const columns=[['ردیف',8],['حوزه سازمانی',36],['ظرفیت مصوب',16],['نیروی فعلی',18],['درصد پوشش',16],['پست خالی',14],['درصد پست خالی',18],['زن',10],['مرد',10],['رسمی',12],['حفظ پست',14],['شرکتی',12],['حجمی',12],['مشاور',12],['پست با نام',14],['خارج چارت',14],['مازاد فعلی',14]];
  const data=rows.map((r,i)=>[i+1,r.label,r.approved,r.operational,r.currentPercent+'٪',r.emptyPosts,r.emptyPercent+'٪',r.female,r.male,r.breakdownFormal,r.breakdownHold,r.breakdownCompany,r.breakdownVolume,r.breakdownConsultant,r.breakdownNamed,r.breakdownOutside,r.operationalSurplus]);
  const scope=scopeLabel(state.statusScope),m=statusMetrics();
  downloadProfessionalXlsx({title:'گزارش وضعیت چارت، ترکیب نیرو و پست‌های خالی',subtitle:`حوزه مورد بررسی: ${scope} — مبنای نیروی فعلی: حوزه فعالیت`,sheetName:'وضعیت چارت',columns,rows:data,summary:[['ظرفیت مصوب',m.approved],['نیروی فعلی',m.operational],['درصد پوشش',m.currentPercent+'٪'],['پست خالی',m.emptyPosts],['درصد پست خالی',m.emptyPercent+'٪'],['زن',m.female],['مرد',m.male],['رسمی',m.breakdownFormal],['شرکتی',m.breakdownCompany],['حجمی',m.breakdownVolume],['مشاور',m.breakdownConsultant]],filename:`وضعیت-چارت-ترکیب-و-پست-خالی-${scope}.xlsx`});
};


/* v4.0.83 — refined status dashboard
   - تفکیک متنی فقط وضعیت‌های دارای مقدار را نمایش می‌دهد.
   - پنل روند تغییرات حذف شده است.
   - نمودار ترکیب نیرو و پست خالی با برچسب‌ها و راهنمای خواناتر بازطراحی شده است. */
org82Colors.volume='#c4b5fd';

statusBreakdownTextPanel=function(data){
  const defs=[
    {key:'breakdownFormal',label:'رسمی',cls:'formal'},
    {key:'breakdownCompany',label:'شرکتی',cls:'company'},
    {key:'breakdownVolume',label:'حجمی',cls:'volume'},
    
    {key:'breakdownConsultant',label:'مشاور',cls:'consultant'},
    {key:'breakdownHold',label:'حفظ پست',cls:'hold'},
    {key:'breakdownNamed',label:'پست با نام',cls:'named'},
    {key:'breakdownOutside',label:'خارج چارت',cls:'outside'},
    {key:'emptyPosts',label:'پست خالی',cls:'empty'}
  ];
  const columns=(data||[]).map(d=>{
    const m=d.metrics||{};
    const active=defs.map(x=>({...x,value:Number(m[x.key]||0)})).filter(x=>x.value>0);
    const chips=active.length
      ?active.map(x=>`<span class="${x.cls}"><i></i><em>${x.label}</em><b>${fa(x.value)}</b></span>`).join('')
      :'<div class="org83-empty-breakdown">مورد ثبت‌شده‌ای برای نمایش وجود ندارد</div>';
    const genderUnknown=m.unknownGender?`<small>نامشخص ${fa(m.unknownGender)}</small>`:'';
    return `<section class="status-breakdown-text-column org83-status-column"><header><strong>${esc(d.label)}</strong><small>ظرفیت ${fa(m.approved||0)} • نیروی فعلی ${fa(m.operational||0)} • پوشش ${fa(m.currentPercent||0)}٪</small></header><div class="status-breakdown-chip-stack">${chips}</div><footer><span class="female">زن <b>${fa(m.female||0)}</b></span><span class="male">مرد <b>${fa(m.male||0)}</b></span>${genderUnknown}</footer></section>`;
  }).join('');
  return `<aside class="status-breakdown-text-panel org82-column-breakdown org83-column-breakdown"><div class="org82-breakdown-head"><div><h4>تفکیک متنی وضعیت</h4><p>در هر ستون فقط وضعیت‌های دارای مقدار نمایش داده می‌شوند.</p></div><span>مبنای نیروی فعلی: حوزه فعالیت</span></div><div class="status-breakdown-text-columns">${columns}</div></aside>`;
};

renderStatusHistory=function(){};

function org83PieSvg(items){
  const active=items.filter(x=>Number(x.value||0)>0);
  const total=Math.max(1,active.reduce((a,x)=>a+Number(x.value||0),0));
  const cx=180,cy=180,r=148;let angle=0;const sectors=[];
  active.forEach(item=>{
    const value=Number(item.value||0),span=value/total*360,start=angle,end=angle+span,mid=start+span/2,pct=Math.round(value/total*100);
    if(span>=359.999){
      sectors.push(`<circle cx="${cx}" cy="${cy}" r="${r}" fill="${item.color}" stroke="#071421" stroke-width="5"/>`);
    }else{
      sectors.push(`<path d="${org82PiePath(cx,cy,r,start,end)}" fill="${item.color}" stroke="#071421" stroke-width="5" stroke-linejoin="round"/>`);
    }
    if(pct>=8){
      const lp=org82Polar(cx,cy,r*.61,mid),dark=item.color==='#f5f7fa'||item.color==='#c4b5fd';
      sectors.push(`<text x="${lp.x}" y="${lp.y-4}" text-anchor="middle" class="org83-pie-slice-label${dark?' dark':''}">${esc(item.shortLabel||item.label)}</text><text x="${lp.x}" y="${lp.y+17}" text-anchor="middle" class="org83-pie-slice-value${dark?' dark':''}">${fa(pct)}٪</text>`);
    }
    angle=end;
  });
  if(!active.length)sectors.push(`<circle cx="${cx}" cy="${cy}" r="${r}" fill="#203247" stroke="#071421" stroke-width="5"/>`);
  return `<svg class="org83-pie-svg" viewBox="0 0 360 360" role="img" aria-label="نمودار ترکیب نیروی فعلی و پست‌های خالی"><circle cx="${cx}" cy="${cy}" r="${r+5}" fill="none" stroke="rgba(93,164,229,.18)" stroke-width="2"/>${sectors.join('')}</svg>`;
}

renderStatusComposition=function(m){
  const items=[
    {label:'رسمی حاضر',shortLabel:'رسمی',value:Number(m.formalActive||0),color:org82Colors.formal},
    {label:'شرکتی',shortLabel:'شرکتی',value:Number(m.groups['شرکتی']||0),color:org82Colors.company},
    {label:'حجمی',shortLabel:'حجمی',value:Number(m.groups['حجمی']||0),color:org82Colors.volume},
    {label:'پیمانکاری',shortLabel:'پیمانکاری',value:Number(m.groups['پیمانکاری']||0),color:org82Colors.contract},
    {label:'مشاور',shortLabel:'مشاور',value:Number(m.groups['مشاور']||0),color:org82Colors.consultant},
    {label:'پست خالی',shortLabel:'خالی',value:Number(m.emptyPosts||0),color:org82Colors.empty}
  ];
  const active=items.filter(x=>x.value>0);
  const total=active.reduce((a,x)=>a+x.value,0),workforce=Number(m.operational||0),approved=Number(m.approved||0);
  const legend=active.map(x=>{
    const pct=total?Math.round(x.value/total*100):0;
    return `<article class="org83-composition-item" style="--c:${x.color}"><i></i><div><strong>${x.label}</strong><small>${fa(pct)}٪ از مجموع نمایش‌داده‌شده</small></div><b>${fa(x.value)}</b></article>`;
  }).join('')||'<div class="org83-empty-composition">داده‌ای برای نمایش وجود ندارد</div>';
  $('#statusComposition').innerHTML=`<div class="org83-composition-summary"><span><small>نیروی فعلی</small><b>${fa(workforce)}</b></span><span><small>پست خالی</small><b>${fa(m.emptyPosts||0)}</b></span><span><small>ظرفیت مصوب</small><b>${fa(approved)}</b></span></div><div class="org83-composition-layout"><div class="org83-pie-card">${org83PieSvg(active)}<div class="org83-pie-foot"><b>${fa(total)}</b><span>جمع نیروی فعلی و ظرفیت خالی نمایش‌داده‌شده</span></div></div><div class="org83-composition-legend">${legend}</div></div>`;
};

