/* v4.0.84 — full pie labels + professional PowerPoint-only reports */
org82Colors.volume='#67e8f9';

function org84CompositionItems(m){
  return [
    {label:'رسمی حاضر',shortLabel:'رسمی',value:Number(m.formalActive||0),color:org82Colors.formal},
    {label:'شرکتی',shortLabel:'شرکتی',value:Number(m.groups?.['شرکتی']||0),color:org82Colors.company},
    {label:'حجمی',shortLabel:'حجمی',value:Number(m.groups?.['حجمی']||0),color:org82Colors.volume},
    {label:'پیمانکاری',shortLabel:'پیمانکاری',value:Number(m.groups?.['پیمانکاری']||0),color:org82Colors.contract},
    {label:'مشاور',shortLabel:'مشاور',value:Number(m.groups?.['مشاور']||0),color:org82Colors.consultant},
    {label:'حفظ پست',shortLabel:'حفظ',value:Number(m.breakdownHold||0),color:org82Colors.hold},
    {label:'پست با نام',shortLabel:'با نام',value:Number(m.breakdownNamed||0),color:org82Colors.named},
    {label:'خارج چارت',shortLabel:'خارج',value:Number(m.breakdownOutside||0),color:org82Colors.outside},
    {label:'پست خالی',shortLabel:'خالی',value:Number(m.emptyPosts||0),color:org82Colors.empty}
  ].filter(x=>x.value>0);
}
function org84PieSvg(items){
  const active=(items||[]).filter(x=>Number(x.value||0)>0),total=Math.max(1,active.reduce((a,x)=>a+Number(x.value||0),0));
  const cx=180,cy=180,r=148;let angle=0;const sectors=[];
  active.forEach((item,idx)=>{
    const value=Number(item.value||0),span=value/total*360,start=angle,end=angle+span,mid=start+span/2,pct=Math.round(value/total*100);
    const dark=['#f5f7fa','#67e8f9','#c4b5fd'].includes(String(item.color||'').toLowerCase());
    if(span>=359.999)sectors.push(`<circle cx="${cx}" cy="${cy}" r="${r}" fill="${item.color}" stroke="#071421" stroke-width="5"/>`);
    else sectors.push(`<path d="${org82PiePath(cx,cy,r,start,end)}" fill="${item.color}" stroke="#071421" stroke-width="5" stroke-linejoin="round"/>`);
    const rr=pct<5?r*.82:(pct<10?r*.72:r*.60),lp=org82Polar(cx,cy,rr,mid);
    const cls=`org84-pie-all-label${dark?' dark':''}${pct<6?' tiny':pct<10?' small':''}`;
    const txt=pct<5?`${fa(pct)}٪`:`${item.shortLabel||item.label} ${fa(pct)}٪`;
    sectors.push(`<text x="${lp.x}" y="${lp.y}" text-anchor="middle" dominant-baseline="middle" class="${cls}">${esc(txt)}</text>`);
    angle=end;
  });
  if(!active.length)sectors.push(`<circle cx="${cx}" cy="${cy}" r="${r}" fill="#203247" stroke="#071421" stroke-width="5"/>`);
  return `<svg class="org83-pie-svg org84-pie-svg" viewBox="0 0 360 360" role="img" aria-label="نمودار ترکیب نیروی فعلی و پست‌های خالی"><circle cx="${cx}" cy="${cy}" r="${r+5}" fill="none" stroke="rgba(93,164,229,.20)" stroke-width="2"/>${sectors.join('')}</svg>`;
}
