  const legend=active.map(x=>{const pct=total?Math.round(x.value/total*100):0;return `<article class="org83-composition-item org84-composition-item" style="--c:${x.color}"><i></i><div><strong>${x.label}</strong><small>${fa(pct)}٪ از مجموع نمایش‌داده‌شده</small></div><b>${fa(x.value)}</b></article>`}).join('')||'<div class="org83-empty-composition">داده‌ای برای نمایش وجود ندارد</div>';
  $('#statusComposition').innerHTML=`<div class="org83-composition-summary"><span><small>نیروی فعلی</small><b>${fa(workforce)}</b></span><span><small>پست خالی</small><b>${fa(m.emptyPosts||0)}</b></span><span><small>ظرفیت مصوب</small><b>${fa(approved)}</b></span></div><div class="org83-composition-layout org84-composition-layout"><div class="org83-pie-card org84-pie-card">${org84PieSvg(active)}<div class="org83-pie-foot"><b>${fa(total)}</b><span>همه وضعیت‌های دارای داده با درصد داخل دایره نمایش داده شده‌اند</span></div></div><div class="org83-composition-legend org84-composition-legend">${legend}</div></div>`;
