function org84EnsureStatusCatalog(){if(!state.statusCatalog||!state.statusCatalog.length){buildStatusCatalog();fillStatusScopes?.();}}
function org84ReportPages(){return Array.from({length:52},(_,i)=>i+2).filter(p=>!!getSlide(p));}
function org84ScopeRowsForPage(page){
  const old=state.statusScope;
  const key='slide:'+page;
  const metrics=statusMetrics(key);
  let children=[];
  try{children=statusDirectChildren(key).map(x=>({...x,metrics:statusMetrics(x.key)}));}catch(e){children=[];}
  state.statusScope=old;
  return {key,page,title:getSlide(page)?.title||scopeLabel(key),metrics,children};
}
function org84PptEsc(v){return excelXmlEscape(String(v??''));}
function org84Hex(v){return String(v||'#ffffff').replace('#','').toUpperCase().slice(0,6).padEnd(6,'0');}
function org84Emu(inch){return Math.round(inch*914400);}
function org84Shape(id,x,y,w,h,fill='#11263d',stroke='#315d89',round=true){
  return `<p:sp><p:nvSpPr><p:cNvPr id="${id}" name="shape${id}"/><p:cNvSpPr/><p:nvPr/></p:nvSpPr><p:spPr><a:xfrm><a:off x="${org84Emu(x)}" y="${org84Emu(y)}"/><a:ext cx="${org84Emu(w)}" cy="${org84Emu(h)}"/></a:xfrm><a:prstGeom prst="${round?'roundRect':'rect'}"><a:avLst/></a:prstGeom><a:solidFill><a:srgbClr val="${org84Hex(fill)}"/></a:solidFill><a:ln w="12700"><a:solidFill><a:srgbClr val="${org84Hex(stroke)}"/></a:solidFill></a:ln></p:spPr></p:sp>`;
}
function org84Text(id,x,y,w,h,text,{size=18,bold=false,color='#FFFFFF',align='r'}={}){
  const paras=String(text??'').split(/\n/).map(line=>`<a:p><a:pPr rtl="1" algn="${align}"/><a:r><a:rPr lang="fa-IR" sz="${Math.round(size*100)}"${bold?' b="1"':''}><a:solidFill><a:srgbClr val="${org84Hex(color)}"/></a:solidFill><a:latin typeface="Arial"/><a:cs typeface="Arial"/></a:rPr><a:t>${org84PptEsc(line)}</a:t></a:r><a:endParaRPr lang="fa-IR" sz="${Math.round(size*100)}"/></a:p>`).join('');
  return `<p:sp><p:nvSpPr><p:cNvPr id="${id}" name="text${id}"/><p:cNvSpPr txBox="1"/><p:nvPr/></p:nvSpPr><p:spPr><a:xfrm><a:off x="${org84Emu(x)}" y="${org84Emu(y)}"/><a:ext cx="${org84Emu(w)}" cy="${org84Emu(h)}"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom><a:noFill/><a:ln><a:noFill/></a:ln></p:spPr><p:txBody><a:bodyPr rtlCol="1" anchor="mid"/><a:lstStyle/>${paras}</p:txBody></p:sp>`;
}
function org84Card(id,x,y,w,h,title,value,color){
  return org84Shape(id,x,y,w,h,'#11263D',color,true)+org84Text(id+1,x+.18,y+.16,w-.36,.28,title,{size:10,color:'#BFD7EF'})+org84Text(id+2,x+.18,y+.45,w-.36,.38,fa(value),{size:22,bold:true,color:'#FFFFFF'});
}
function org84Bar(id,x,y,w,h,label,value,max,color){
  const bw=max?Math.max(.04,w*value/max):0;
  return org84Text(id,x,y-.04,1.65,h,label,{size:9,color:'#DFEFFF'})+org84Shape(id+1,x+1.75,y,w,h,'#0B1B2B','#1D3B59',true)+org84Shape(id+2,x+1.75,y,bw,h,color,color,true)+org84Text(id+3,x+1.75,y,w-.1,h,fa(value),{size:9,bold:true,color:'#FFFFFF',align:'l'});
}
function org84SlideXml(content){return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><p:sld xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main"><p:cSld><p:bg><p:bgPr><a:solidFill><a:srgbClr val="081524"/></a:solidFill></p:bgPr></p:bg><p:spTree><p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr><p:grpSpPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="0" cy="0"/><a:chOff x="0" y="0"/><a:chExt cx="0" cy="0"/></a:xfrm></p:grpSpPr>${content}</p:spTree></p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sld>`;}
function org84CoverSlide(title,subtitle){
  let id=10,c='';c+=org84Shape(id++,0,0,13.333,7.5,'#081524','#081524',false);c+=org84Shape(id++,0.35,0.35,12.63,6.8,'#0F2238','#315D89',true);c+=org84Text(id++,1,1.2,11.3,.65,title,{size:30,bold:true,color:'#FFFFFF',align:'c'});c+=org84Text(id++,1,2.02,11.3,.45,subtitle,{size:14,color:'#A8C6E5',align:'c'});c+=org84Text(id++,1,3.1,11.3,.65,'گزارش حرفه‌ای وضعیت چارت و ترکیب نیروی انسانی',{size:22,bold:true,color:'#67E8F9',align:'c'});c+=org84Text(id++,1,5.55,11.3,.35,new Date().toLocaleString('fa-IR'),{size:11,color:'#9EB9D7',align:'c'});return org84SlideXml(c);
}
function org84StatusSlide(pageData,idx,total){
  const m=pageData.metrics,items=org84CompositionItems(m),max=Math.max(1,...items.map(x=>x.value));let id=20,c='';
  c+=org84Shape(id++,0,0,13.333,7.5,'#081524','#081524',false);
  c+=org84Text(id++,0.55,.25,9.2,.42,pageData.title,{size:21,bold:true,color:'#FFFFFF'});
  c+=org84Text(id++,10.2,.28,2.55,.3,`صفحه ${fa(pageData.page)} از ۵۳`,{size:10,color:'#9EB9D7',align:'l'});
  c+=org84Card(id,.55,.9,2.8,.75,'ظرفیت مصوب',m.approved,'#4F9CFF');id+=3;
  c+=org84Card(id,3.58,.9,2.8,.75,'نیروی فعلی',m.operational,'#19D3D1');id+=3;
  c+=org84Card(id,6.62,.9,2.8,.75,'پست خالی',m.emptyPosts,'#EF4444');id+=3;
  c+=org84Card(id,9.65,.9,2.8,.75,'درصد پوشش',`${fa(m.currentPercent)}٪`,'#36D17C');id+=3;
  c+=org84Shape(id++,0.55,1.95,5.95,4.92,'#0D1D30','#274A70',true);
  c+=org84Text(id++,0.85,2.12,5.35,.32,'ترکیب وضعیت حوزه',{size:15,bold:true,color:'#FFFFFF'});
  items.forEach((x,i)=>{c+=org84Bar(id,0.85,2.62+i*.45,4.95,.22,x.label,x.value,max,x.color);id+=4;});
  c+=org84Shape(id++,6.78,1.95,5.95,4.92,'#0D1D30','#274A70',true);
  c+=org84Text(id++,7.08,2.12,5.35,.32,'شاخص‌های مدیریتی',{size:15,bold:true,color:'#FFFFFF'});
  const bullets=[`زن: ${fa(m.female||0)}    مرد: ${fa(m.male||0)}`,`رسمی حاضر: ${fa(m.formalActive||0)}    حفظ پست: ${fa(m.breakdownHold||0)}`,`شرکتی: ${fa(m.groups?.['شرکتی']||0)}    حجمی: ${fa(m.groups?.['حجمی']||0)}`,`پیمانکاری: ${fa(m.groups?.['پیمانکاری']||0)}    مشاور: ${fa(m.groups?.['مشاور']||0)}`,`پست با نام: ${fa(m.breakdownNamed||0)}    خارج چارت: ${fa(m.breakdownOutside||0)}`];
  bullets.forEach((b,i)=>{c+=org84Text(id++,7.12,2.62+i*.48,5.2,.32,b,{size:12,color:'#D9EBFF'});});
  const children=(pageData.children||[]).slice(0,6);
  c+=org84Text(id++,7.08,5.2,5.35,.28,'زیرمجموعه‌های شاخص',{size:12,bold:true,color:'#67E8F9'});
  children.forEach((ch,i)=>{c+=org84Text(id++,7.12,5.55+i*.25,5.2,.22,`${ch.label}: ${fa(ch.metrics.operational)} نفر، ${fa(ch.metrics.emptyPosts)} خالی`,{size:8.5,color:'#BFD7EF'});});
  c+=org84Text(id++,0.55,7.04,12.2,.25,`گزارش خودکار سامانه هوشمند منابع انسانی — اسلاید ${fa(idx)} از ${fa(total)}`,{size:8,color:'#7895B2',align:'c'});
  return org84SlideXml(c);
}
function org84SummarySlide(pages){
  const sum=pages.reduce((a,p)=>{const m=p.metrics;a.approved+=m.approved||0;a.operational+=m.operational||0;a.empty+=m.emptyPosts||0;a.female+=m.female||0;a.male+=m.male||0;return a},{approved:0,operational:0,empty:0,female:0,male:0});
  let id=10,c='';c+=org84Shape(id++,0,0,13.333,7.5,'#081524','#081524',false);c+=org84Text(id++,0.7,.45,12,.5,'خلاصه مدیریتی تمام صفحات چارت',{size:24,bold:true,color:'#FFFFFF',align:'c'});
  c+=org84Card(id,1.0,1.35,2.8,.9,'کل ظرفیت مصوب',sum.approved,'#4F9CFF');id+=3;c+=org84Card(id,4.0,1.35,2.8,.9,'کل نیروی فعلی',sum.operational,'#19D3D1');id+=3;c+=org84Card(id,7.0,1.35,2.8,.9,'کل پست خالی',sum.empty,'#EF4444');id+=3;c+=org84Card(id,10.0,1.35,2.3,.9,'پوشش کل',sum.approved?Math.round(sum.operational/sum.approved*100)+'٪':'۰٪','#36D17C');id+=3;
  c+=org84Shape(id++,1,2.7,11.35,2.9,'#0D1D30','#274A70',true);c+=org84Text(id++,1.35,3,10.65,.4,'این فایل شامل یک اسلاید حرفه‌ای برای هر صفحه کاری چارت از صفحه ۲ تا ۵۳ است و برای ارائه مدیریتی، جلسه منابع انسانی و بررسی ظرفیت واحدها آماده شده است.',{size:16,color:'#D9EBFF',align:'c'});c+=org84Text(id++,1.35,4.05,10.65,.35,`زن: ${fa(sum.female)}     مرد: ${fa(sum.male)}     تعداد صفحات گزارش: ${fa(pages.length)}`,{size:18,bold:true,color:'#67E8F9',align:'c'});
  return org84SlideXml(c);
}
function org84ThemeXml(){return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><a:theme xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" name="SazmanHR"><a:themeElements><a:clrScheme name="SazmanHR"><a:dk1><a:srgbClr val="081524"/></a:dk1><a:lt1><a:srgbClr val="FFFFFF"/></a:lt1><a:dk2><a:srgbClr val="0D1D30"/></a:dk2><a:lt2><a:srgbClr val="D9EBFF"/></a:lt2><a:accent1><a:srgbClr val="36D17C"/></a:accent1><a:accent2><a:srgbClr val="19D3D1"/></a:accent2><a:accent3><a:srgbClr val="EF4444"/></a:accent3><a:accent4><a:srgbClr val="67E8F9"/></a:accent4><a:accent5><a:srgbClr val="4F9CFF"/></a:accent5><a:accent6><a:srgbClr val="8B4F25"/></a:accent6><a:hlink><a:srgbClr val="4F9CFF"/></a:hlink><a:folHlink><a:srgbClr val="67E8F9"/></a:folHlink></a:clrScheme><a:fontScheme name="Arial"><a:majorFont><a:latin typeface="Arial"/><a:cs typeface="Arial"/></a:majorFont><a:minorFont><a:latin typeface="Arial"/><a:cs typeface="Arial"/></a:minorFont></a:fontScheme><a:fmtScheme name="SazmanHR"><a:fillStyleLst><a:solidFill><a:srgbClr val="081524"/></a:solidFill></a:fillStyleLst><a:lnStyleLst><a:ln w="12700"><a:solidFill><a:srgbClr val="315D89"/></a:solidFill></a:ln></a:lnStyleLst><a:effectStyleLst><a:effectStyle/></a:effectStyleLst><a:bgFillStyleLst><a:solidFill><a:srgbClr val="081524"/></a:solidFill></a:bgFillStyleLst></a:fmtScheme></a:themeElements><a:objectDefaults/><a:extraClrSchemeLst/></a:theme>`}
function org84BuildPptx(selected='all'){
  org84EnsureStatusCatalog();
  const selectedPages=selected&&selected!=='all52'?[Number(selected.replace('slide:',''))].filter(Boolean):org84ReportPages();
  const pages=selectedPages.map(org84ScopeRowsForPage);
  const slideXml=[org84CoverSlide('سامانه هوشمند منابع انسانی','گزارش PowerPoint حرفه‌ای وضعیت چارت'),org84SummarySlide(pages),...pages.map((p,i)=>org84StatusSlide(p,i+3,pages.length+2))];
  const files=[];
  const overrides=slideXml.map((_,i)=>`<Override PartName="/ppt/slides/slide${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slide+xml"/>`).join('');
  files.push({name:'[Content_Types].xml',data:`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/ppt/presentation.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.presentation.main+xml"/><Override PartName="/ppt/slideMasters/slideMaster1.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slideMaster+xml"/><Override PartName="/ppt/slideLayouts/slideLayout1.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slideLayout+xml"/><Override PartName="/ppt/theme/theme1.xml" ContentType="application/vnd.openxmlformats-officedocument.theme+xml"/>${overrides}</Types>`});
  files.push({name:'_rels/.rels',data:`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="ppt/presentation.xml"/></Relationships>`});
  const sldIds=slideXml.map((_,i)=>`<p:sldId id="${256+i}" r:id="rId${i+2}"/>`).join('');
  files.push({name:'ppt/presentation.xml',data:`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><p:presentation xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main"><p:sldMasterIdLst><p:sldMasterId id="2147483648" r:id="rId1"/></p:sldMasterIdLst><p:sldIdLst>${sldIds}</p:sldIdLst><p:sldSz cx="12192000" cy="6858000" type="screen4x3"/><p:notesSz cx="6858000" cy="9144000"/></p:presentation>`});
  const presRels=[`<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideMaster" Target="slideMasters/slideMaster1.xml"/>`,...slideXml.map((_,i)=>`<Relationship Id="rId${i+2}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slide" Target="slides/slide${i+1}.xml"/>`)].join('');
  files.push({name:'ppt/_rels/presentation.xml.rels',data:`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${presRels}</Relationships>`});
  files.push({name:'ppt/slideMasters/slideMaster1.xml',data:`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><p:sldMaster xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main"><p:cSld><p:spTree><p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr><p:grpSpPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="0" cy="0"/><a:chOff x="0" y="0"/><a:chExt cx="0" cy="0"/></a:xfrm></p:grpSpPr></p:spTree></p:cSld><p:clrMap bg1="dk1" tx1="lt1" bg2="dk2" tx2="lt2" accent1="accent1" accent2="accent2" accent3="accent3" accent4="accent4" accent5="accent5" accent6="accent6" hlink="hlink" folHlink="folHlink"/><p:sldLayoutIdLst><p:sldLayoutId id="2147483649" r:id="rId1"/></p:sldLayoutIdLst><p:txStyles><p:titleStyle/><p:bodyStyle/><p:otherStyle/></p:txStyles></p:sldMaster>`});
  files.push({name:'ppt/slideMasters/_rels/slideMaster1.xml.rels',data:`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideLayout" Target="../slideLayouts/slideLayout1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/theme" Target="../theme/theme1.xml"/></Relationships>`});
  files.push({name:'ppt/slideLayouts/slideLayout1.xml',data:`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><p:sldLayout xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main" type="blank" preserve="1"><p:cSld name="Blank"><p:spTree><p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr><p:grpSpPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="0" cy="0"/><a:chOff x="0" y="0"/><a:chExt cx="0" cy="0"/></a:xfrm></p:grpSpPr></p:spTree></p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sldLayout>`});
  files.push({name:'ppt/slideLayouts/_rels/slideLayout1.xml.rels',data:`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideMaster" Target="../slideMasters/slideMaster1.xml"/></Relationships>`});
  files.push({name:'ppt/theme/theme1.xml',data:org84ThemeXml()});
  slideXml.forEach((xml,i)=>{files.push({name:`ppt/slides/slide${i+1}.xml`,data:xml});files.push({name:`ppt/slides/_rels/slide${i+1}.xml.rels`,data:`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideLayout" Target="../slideLayouts/slideLayout1.xml"/></Relationships>`});});
  return zipStore(files);
}
function org84DownloadPowerPoint(){
  try{
    const value=$('#reportUnit')?.value||'all52';
    const bytes=org84BuildPptx(value);
    const blob=new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.presentationml.presentation'});
    const name=value==='all52'?'گزارش-PowerPoint-تمام-صفحات-چارت-منابع-انسانی.pptx':`گزارش-PowerPoint-${safeFileName(scopeLabel(value))}.pptx`;
    downloadBlob(blob,name);toast('گزارش PowerPoint آماده شد',value==='all52'?'همه صفحات ۲ تا ۵۳ در فایل پاورپوینت حرفه‌ای قرار گرفت.':'گزارش پاورپوینت بخش انتخاب‌شده آماده شد.');
  }catch(e){console.error(e);toast('خروجی PowerPoint ساخته نشد',e.message||String(e),'error');}
}
function org84ReportPreview(){
  const value=$('#reportUnit')?.value||'all52';
  const pages=value==='all52'?org84ReportPages():[Number(value.replace('slide:',''))].filter(Boolean);
  $('#reportResult').dataset.reportKind='pptx';$('#reportResult').dataset.ids='';$('#reportResult').dataset.nodeRows='';
  const cards=pages.slice(0,8).map(p=>{const m=statusMetrics('slide:'+p),title=getSlide(p)?.title||('صفحه '+p);return `<article class="org84-ppt-preview-card"><strong>${esc(title)}</strong><span>صفحه ${fa(p)}</span><p>ظرفیت ${fa(m.approved)} • نیروی فعلی ${fa(m.operational)} • پست خالی ${fa(m.emptyPosts)}</p></article>`}).join('');
  $('#reportResult').innerHTML=`<div class="org84-ppt-preview"><div><h3>گزارش PowerPoint حرفه‌ای</h3><p>${value==='all52'?'تمام صفحات کاری ۲ تا ۵۳':'بخش انتخاب‌شده'} با قالب مدیریتی، شاخص‌های وضعیت، ترکیب نیرو، پست‌های خالی و تفکیک جنسیت آماده خروجی است.</p><button class="primary" id="org84DownloadPptx">دانلود PowerPoint</button></div><div class="org84-ppt-preview-grid">${cards}</div></div>`;
  $('#org84DownloadPptx').onclick=org84DownloadPowerPoint;
}
const org84PreviousRenderReports=renderReports;
renderReports=function(){
  org84EnsureStatusCatalog();
  $('#reportCards').innerHTML=`<article class="report-card org84-ppt-report-card" data-report="ppt-all"><span>▣</span><h3>گزارش PowerPoint تمام بخش‌ها</h3><p>یک فایل ارائه حرفه‌ای برای صفحات ۲ تا ۵۳ با شاخص‌های ظرفیت، نیروی فعلی، پست خالی و ترکیب وضعیت.</p></article><article class="report-card org84-ppt-report-card" data-report="ppt-selected"><span>◆</span><h3>گزارش PowerPoint بخش انتخاب‌شده</h3><p>برای جلسه، چاپ یا ارائه مدیران؛ استاندارد، تمیز و هماهنگ با تم سامانه.</p></article>`;
  $$('[data-report="ppt-all"]').forEach(x=>x.onclick=()=>{$('#reportUnit').value='all52';org84ReportPreview();});
  $$('[data-report="ppt-selected"]').forEach(x=>x.onclick=()=>org84ReportPreview());
  org84ReportPreview();
};
fillReportUnits=function(){
  const sel=$('#reportUnit');if(!sel)return;const pages=org84ReportPages();
  sel.innerHTML=`<option value="all52">تمام صفحات ۲ تا ۵۳</option>`+pages.map(p=>`<option value="slide:${p}">صفحه ${fa(p)} — ${esc(getSlide(p)?.title||'بخش سازمانی')}</option>`).join('');
};
buildReport=function(){org84ReportPreview();};
downloadReport=function(){org84DownloadPowerPoint();};


/* v4.0.86 — personnel service-history timeline with exact total
   ریز سابقه هر شخص از فایل «ریز سابقه.XLS» در بخش مشخصات پرسنلی نمایش داده می‌شود. */
function org85HistoryForPerson(person){
  const no=String(person?.personnel_no||'').replace(/\D/g,'');
  return window.SERVICE_HISTORY?.byPersonnelNo?.[no]||null;
}
function org85HistoryChip(text,cls=''){
  if(empty(text))return'';
  return `<span class="service-history-chip ${esc(cls)}">${esc(text)}</span>`;
}
function org85HistoryCard(person){
  const h=org85HistoryForPerson(person);
  if(!h){
    return `<section class="service-history-card service-history-empty">
      <div class="service-history-head">
        <div><span class="service-history-eyebrow">تاریخچه خدمت</span><h3>ریز سابقه</h3><p>شماره پرسنلی ${esc(person?.personnel_no||'—')}</p></div>
        <strong class="service-history-count">۰ دوره</strong>
      </div>
      <div class="service-history-empty-state"><span>⌁</span><div><b>ریز سابقه‌ای در فایل مرجع ثبت نشده است.</b><p>در صورت دریافت فایل تکمیلی، دوره‌های خدمت همین‌جا نمایش داده می‌شوند.</p></div></div>
    </section>`;
  }
  const periods=[...(h.periods||[])].sort((a,b)=>String(b.from||'').localeCompare(String(a.from||''),'fa')||String(b.to||'').localeCompare(String(a.to||''),'fa'));
  const items=periods.map((x,i)=>{
    const role=org76FaText(x.role||'عنوان فعالیت ثبت نشده');
    const unit=org76FaText(x.unit||x.service_location||'واحد سازمانی ثبت نشده');
    const dateText=[x.from?`از ${org76FaText(x.from)}`:'',x.to?`تا ${org76FaText(x.to)}`:''].filter(Boolean).join(' ');
    const chips=[
      org85HistoryChip(x.history_type,x.history_type==='داخل'?'inside':''),
      org85HistoryChip(x.relation,'relation'),
      org85HistoryChip(x.service_location?`محل خدمت: ${x.service_location}`:'','location')
    ].join('');
    return `<article class="service-history-item ${i===0?'latest':''}">
      <div class="service-history-marker"><i></i></div>
      <div class="service-history-body">
        <div class="service-history-period"><b>${esc(dateText||'بازه زمانی ثبت نشده')}</b>${x.duration?`<span>${esc(org76FaText(x.duration))}</span>`:''}</div>
        <h4>${esc(role)}</h4>
        <p>${esc(unit)}</p>
        ${chips?`<div class="service-history-chips">${chips}</div>`:''}
      </div>
    </article>`;
  }).join('');
  return `<section class="service-history-card">
    <div class="service-history-head">
      <div><span class="service-history-eyebrow">تاریخچه خدمت</span><h3>ریز سابقه</h3><p>منبع: ریز سابقه.XLS — جدیدترین دوره در ابتدای فهرست</p></div>
      <strong class="service-history-count">${fa(h.period_count||periods.length)} دوره</strong>
    </div>
    <div class="service-history-total">
      <div><span>جمع کل سابقه</span><b>${esc(h.total_duration||'۰ روز')}</b><small>${fa(h.total_days||0)} روز ثبت‌شده بدون تکرار</small></div>
      <strong>${fa(h.merged_period_count||1)} بازه پیوسته</strong>
    </div>
    <div class="service-history-kpis">
      <div><span>شروع سابقه ثبت‌شده</span><b>${esc(h.first_from||'—')}</b></div>
      <div><span>آخرین تاریخ ثبت‌شده</span><b>${esc(h.last_to||'—')}</b></div>
      <div><span>واحدهای متمایز</span><b>${fa(h.unit_count||0)}</b></div>
    </div>
    <div class="service-history-timeline">${items}</div>
  </section>`;
}
/* v4.1.43 — training history integrated into personnel cards.
   Source: cleaned and normalized educational-course workbook; matched by personnel number. */
function org143TrainingForPerson(person){
  const no=latinDigits(person?.personnel_no||'').replace(/\D/g,'');
  return window.TRAINING_HISTORY_V4143?.byPersonnelNo?.[no]||null;
}
function org143TrainingCard(person){
  const h=org143TrainingForPerson(person);
  if(!h){
    return `<section class="training-history-card training-history-empty" data-training-card>
      <div class="training-history-head"><div><span class="training-history-eyebrow">توسعه سرمایه انسانی</span><h3>سوابق آموزشی</h3><p>شماره پرسنلی ${esc(person?.personnel_no||'—')}</p></div><strong class="training-history-count">۰ دوره</strong></div>
      <div class="training-history-empty-state"><span>◎</span><div><b>سابقه آموزشی ثبت‌شده‌ای برای این شخص یافت نشد.</b><p>اطلاعات فایل دوره‌های آموزشی فقط براساس شماره پرسنلی دقیق به کارت افراد متصل می‌شود.</p></div></div>
    </section>`;
  }
  const years=(h.y||[]).map(y=>`<option value="${esc(y)}">${esc(y)}</option>`).join('');
  return `<section class="training-history-card" data-training-card>
    <div class="training-history-head">
      <div><span class="training-history-eyebrow">توسعه سرمایه انسانی</span><h3>سوابق آموزشی</h3><p>منبع: گزارش دوره‌های آموزشی اصلاح‌شده — جدیدترین دوره در ابتدای فهرست</p></div>
      <strong class="training-history-count">${fa(h.c||0)} دوره</strong>
    </div>
    <div class="training-history-highlight"><div><span>آخرین دوره آموزشی</span><b>${esc(h.x||'عنوان ثبت نشده')}</b><small>${esc(h.d||'تاریخ ثبت نشده')}</small></div><i>↗</i></div>
    <div class="training-history-kpis">
      <div><span>جمع ساعات آموزش</span><b>${fa(h.h||0)}</b><small>ساعت</small></div>
      <div><span>ساعات نظری</span><b>${fa(h.t||0)}</b><small>ساعت</small></div>
      <div><span>ساعات عملی</span><b>${fa(h.p||0)}</b><small>ساعت</small></div>
      <div><span>مجریان متمایز</span><b>${fa(h.v||0)}</b><small>مرکز آموزشی</small></div>
      <div><span>بازه آموزشی</span><b>${esc(h.f||'—')}</b><small>تا ${esc(h.d||'—')}</small></div>
    </div>
    <div class="training-history-tools">
      <label>جست‌وجوی دوره<input type="search" data-training-search placeholder="عنوان، کد یا مجری دوره"></label>
      <label>سال شروع<select data-training-year><option value="">همه سال‌ها</option>${years}</select></label>
      <span data-training-visible>${fa(h.c||0)} دوره</span>
    </div>
    <div class="training-history-table"><table><thead><tr><th>ردیف</th><th>دوره آموزشی</th><th>کد دوره</th><th>مجری</th><th>ساعات</th><th>بازه برگزاری</th></tr></thead><tbody data-training-body></tbody></table></div>
    <div class="training-history-pagination" data-training-pagination></div>
  </section>`;
}
function org143BindTrainingCard(person){
  const card=$('#personModalContent [data-training-card]');
  const h=org143TrainingForPerson(person);if(!card||!h)return;
  const search=card.querySelector('[data-training-search]'),year=card.querySelector('[data-training-year]'),body=card.querySelector('[data-training-body]'),pager=card.querySelector('[data-training-pagination]'),visible=card.querySelector('[data-training-visible]');
  const view={page:1,per:10};
  const render=()=>{
    const q=norm(search?.value||''),selected=year?.value||'';
    const filtered=(h.r||[]).filter(c=>(!selected||String(c[5]||'').startsWith(selected)||String(c[6]||'').startsWith(selected))&&(!q||[c[0],c[1],c[2],c[5],c[6],c[7]].some(v=>norm(v).includes(q))));
    const pages=Math.max(1,Math.ceil(filtered.length/view.per));view.page=Math.min(view.page,pages);
    const start=(view.page-1)*view.per,rows=filtered.slice(start,start+view.per);
    body.innerHTML=rows.length?rows.map((c,i)=>`<tr><td>${fa(start+i+1)}</td><td><b>${esc(c[1]||'—')}</b><small>${esc(c[7]||'')}</small></td><td><code>${esc(c[0]||'—')}</code></td><td>${esc(c[2]||'—')}</td><td><span class="training-hour theory">نظری ${fa(c[3]||0)}</span><span class="training-hour practical">عملی ${fa(c[4]||0)}</span><strong>${fa(Number(c[3]||0)+Number(c[4]||0))} ساعت</strong></td><td><b>${esc(c[5]||'—')}</b><small>تا ${esc(c[6]||'—')}</small></td></tr>`).join(''):`<tr><td colspan="6"><div class="training-no-result">دوره‌ای با این فیلتر پیدا نشد.</div></td></tr>`;
    if(visible)visible.textContent=`${fa(filtered.length)} دوره`;
    pager.innerHTML=`<button type="button" data-training-prev ${view.page<=1?'disabled':''}>قبلی</button><span>صفحه ${fa(view.page)} از ${fa(pages)}</span><button type="button" data-training-next ${view.page>=pages?'disabled':''}>بعدی</button>`;
    const prev=pager.querySelector('[data-training-prev]'),next=pager.querySelector('[data-training-next]');
    if(prev)prev.onclick=()=>{view.page=Math.max(1,view.page-1);render()};
    if(next)next.onclick=()=>{view.page=Math.min(pages,view.page+1);render()};
  };
  if(search)search.oninput=()=>{view.page=1;render()};
  if(year)year.onchange=()=>{view.page=1;render()};
  render();
}

const org85PreviousOpenPerson=openPerson;
openPerson=function(id){
  const p=state.personById.get(id);if(!p)return;
  const needHistory=!window.SERVICE_HISTORY,needDetails=state.role==='admin'&&!Array.isArray(p.raw_fields),needTraining=!window.TRAINING_HISTORY_V4143;
  if(needHistory||needDetails||needTraining){
    $('#personModalContent').innerHTML=`<div class="profile-modal-head"><div class="avatar">${esc((p.name||p.full_name||'؟').slice(0,1))}</div><div><h2>${esc(p.full_name)}</h2><p>در حال بارگذاری جزئیات موردنیاز…</p></div></div><div class="empty-state compact"><div>⌛</div><h3>آماده‌سازی مشخصات پرسنلی</h3><p>ریز سابقه، سوابق آموزشی و اطلاعات خام فقط در اولین مشاهده خوانده می‌شوند تا سامانه سریع بماند.</p></div>`;
    $('#personModal').classList.remove('hidden');
    const jobs=[];if(needHistory)jobs.push(ensureServiceHistory().catch(err=>{console.warn('service-history',err);window.SERVICE_HISTORY={byPersonnelNo:{}}}));if(needTraining)jobs.push(ensureTrainingHistory().catch(err=>{console.warn('training-history',err);window.TRAINING_HISTORY_V4143={byPersonnelNo:{},meta:{}}}));
    if(needDetails)jobs.push(ensurePersonDetails().then(map=>{p.raw_fields=map?.[p.id]||[];p.raw_field_count=p.raw_fields.length}).catch(err=>{console.warn('person-details',err);p.raw_fields=[]}));
    Promise.all(jobs).then(()=>openPerson(id));return;
  }
  if(state.role==='admin'&&!Array.isArray(p.raw_fields)){p.raw_fields=window.PERSON_DETAILS_V413?.[p.id]||[]}
  const tags=[p.named_post?`<span class="status-chip named-chip">${esc(p.named_post_type==='بانام ایثار'?'پست با نام ایثار':'پست با نام')}</span>`:'',p.is_hold_position?'<span class="status-chip warn">حفظ پست</span>':'',p.outside_chart?'<span class="status-chip info">خارج از چارت</span>':''].join(' ');
  const canViewFull=state.role==='admin';
  const raw=canViewFull&&Array.isArray(p.raw_fields)?p.raw_fields.filter(f=>!empty(f.label)&&!empty(f.value)):[];
  const groups={};raw.forEach(f=>{const sec=f.section||'اطلاعات کامل';(groups[sec]||(groups[sec]=[])).push(f)});
  const full=Object.entries(groups).map(([sec,items])=>`<section class="raw-section"><h3>${esc(sec)} <span>${fa(items.length)} فیلد</span></h3><div class="raw-grid">${items.map(f=>dataItem(f.label,f.value)).join('')}</div></section>`).join('');
  const fullCard=canViewFull?`<div class="all-excel-fields"><div class="all-fields-title"><div><h3>مشخصات پرسنلی</h3><p>تمام اطلاعات غیرخالی ثبت‌شده در فایل‌های Excel مرجع، بدون حذف فیلد</p></div><strong class="field-count-badge">${fa(raw.length)} فیلد</strong></div>${full||'<div class="empty-state"><p>اطلاعات تکمیلی برای این رکورد ثبت نشده است.</p></div>'}</div>`:`<div class="viewer-card-notice"><b>جزئیات کامل مشخصات پرسنلی</b><p>به‌دلیل محرمانگی اطلاعات، نمایش همه فیلدهای Excel فقط برای ادمین سامانه فعال است.</p></div>`;
  const historyCard=org85HistoryCard(p),trainingCard=org143TrainingCard(p);
  $('#personModalContent').innerHTML=`<div class="profile-modal-head"><div class="avatar">${esc((p.name||p.full_name||'؟').slice(0,1))}</div><div><h2>${esc(p.full_name)}</h2><p>شماره پرسنلی ${esc(p.personnel_no)} ${tags}</p></div></div><div class="profile-summary"><div class="data-grid">${dataItem('نوع همکاری',p.employment_group+(p.employment_subtype?' — '+p.employment_subtype:''))}${dataItem('عنوان پست',p.position_title)}${dataItem('کد پست',p.position_code)}${dataItem('واحد سازمانی مصوب',p.organizational_unit)}${dataItem('محل خدمت واقعی',p.actual_location)}${dataItem('حوزه فعالیت',p.activity_area)}${dataItem('وضعیت اشتغال',p.status)}${dataItem('شرکت پیمانکار',p.company||'')}${p.outside_chart?dataItem('وضعیت خارج از چارت',p.placement_status||'خارج از چارت — جانمایی مرتبط')+dataItem('دلیل جانمایی خارج از چارت',p.placement_evidence||p.mapping_reason||''):''}${p.employment_group!=='رسمی'?dataItem('وضعیت جانمایی',p.placement_status||'')+dataItem('اطمینان جانمایی',p.placement_confidence?fa(Math.round(Number(p.placement_confidence)*100))+'٪':'')+dataItem('دلیل جانمایی',p.placement_evidence||''):''}</div></div>${historyCard}${trainingCard}${fullCard}${org421Can(ORG421_ACCESS.keys.editData)?`<div class="profile-actions"><button class="secondary" type="button" id="printThisPerson">چاپ مشخصات پرسنلی</button><button class="primary" id="editThisPerson">ویرایش اطلاعات</button></div>`:''}`;
  $('#personModal').classList.remove('hidden');
  if($('#editThisPerson'))$('#editThisPerson').onclick=()=>openPersonEditor(p.id);
  if($('#printThisPerson'))$('#printThisPerson').onclick=()=>window.print();
  org143BindTrainingCard(p);
};


/* v4.0.87 — deterministic HR placement corrections (page 16)
   - هوشیار مومنه: زیر کارشناس بررسی فعالیتهای برون سپاری
   - زهرا ساطعی: همان نود، با رنگ ویژه و مجزا
   - فرزاد جانی: اداره بازنشستگی و رفاه */
const org87PreviousOrg79Cards=org79Cards;
function org87RemovePersonFromCardMap(map,personId){
  map.forEach((items,key)=>{
    const next=[];
    (items||[]).forEach(item=>{
      const kept=(item.people||[]).filter(p=>p&&p.id!==personId);
      if((item.people||[]).length&&kept.length===0)return;
      next.push(kept.length===(item.people||[]).length?item:{...item,people:kept,personId:kept[0]?.id||''});
    });
    map.set(key,next);
  });
}
function org87AddPlacement(map,nodeId,personId,kind,label,rank,note=''){
  const person=state.personById.get(personId);if(!person)return;
  org87RemovePersonFromCardMap(map,personId);
  const node=state.nodeById.get(nodeId);if(!node)return;
  const arr=(map.get(nodeId)||[]).filter(x=>x.kind!=='empty');
  arr.push({kind,label,title:node.text||'',people:[person],personId:person.id,id:`org87-${nodeId}-${person.id}`,main:org76PersonName(person),rank,org77View:org77Mode('formal'),org77Note:note});
  arr.sort(org63StatusSort);map.set(nodeId,arr);
}
org79Cards=function(type,page,slide){
  const map=org87PreviousOrg79Cards(type,page,slide);
  if(+page!==16)return map;
  org87AddPlacement(map,'p16-n29','F-2514','hold','حفظ پست',30,'جانمایی اصلاح‌شده');
  org87AddPlacement(map,'p16-n29','F-2096','specialhold','حفظ پست مرتبط',31,'نمایش ویژه');
  org87AddPlacement(map,'p16-n21','N-9999','nonofficial','حجمی',20,'');
  return map;
};
const org87PreviousRenderChartCornerLegend=renderChartCornerLegend;
renderChartCornerLegend=function(type){
  org87PreviousRenderChartCornerLegend(type);
  const page=type==='formal'?state.formalPage:state.nonPage;if(+page!==16)return;
  const {stage}=chartDom(type);if(!stage)return;
  const host=stage.closest('.chart-layout')||stage;
  const panel=host.querySelector('.chart-color-card .chart-color-popover');if(!panel||panel.querySelector('.specialhold'))return;
  panel.insertAdjacentHTML('beforeend','<div class="chart-color-row specialhold"><i></i><span>ارغوانی</span><b>حفظ پست مرتبط</b></div>');
};


/* v4.0.88 — HR page 16 visual refinements
   1) حذف کارت «پست خالی» اضافی از نود امور کارکنان و رفاه
   2) نمایش زهرا ساطعی به‌صورت نود مستقل ارغوانی و متصل زیر
      «کارشناس بررسی فعالیتهای برون سپاری» */
const org88PreviousOrg79Tree=org79Tree;
org79Tree=function(type,page,slide){
  const tree=org88PreviousOrg79Tree(type,page,slide);
  if(!tree||+page!==16)return tree;
  const parentId='p16-n29';
  if(!tree.byId.has(parentId))return tree;
  const id='org88-satei-standalone';
  if(tree.byId.has(id))return tree;
  const special={
    id,
    text:'زهرا ساطعی',
    page:16,
    count:1,
    is_unit:false,
    org88SpecialHold:true,
    org88PersonId:'F-2096',
    org88Subtitle:'حفظ پست مرتبط'
  };
  tree.nodes.push(special);
  tree.byId.set(id,special);
  tree.parent.set(id,parentId);
  tree.children.set(id,[]);
  const siblings=tree.children.get(parentId)||[];
  siblings.push(special);
  tree.children.set(parentId,siblings);
  return tree;
};
const org88PreviousOrg79Cards=org79Cards;
org79Cards=function(type,page,slide){
  const map=org88PreviousOrg79Cards(type,page,slide);
  if(+page!==16)return map;
  // زهرا ساطعی دیگر کارت داخل نود والد نیست؛ نود مستقل دارد.
  org87RemovePersonFromCardMap(map,'F-2096');
  // جایگاه خالی اضافه در امور کارکنان و رفاه حذف می‌شود.
  map.set('p16-n12',(map.get('p16-n12')||[]).filter(item=>item.kind!=='empty'));
  map.set('org88-satei-standalone',[]);
  return map;
};
const org88PreviousOrg79Metrics=org79Metrics;
org79Metrics=function(node,cards,ctx){
  if(node?.org88SpecialHold){
    return {w:188,h:72,titleH:72,isRoot:false,isUnit:false,cards:[]};
  }
  return org88PreviousOrg79Metrics(node,cards,ctx);
};
const org88PreviousOrg79Post=org79Post;
org79Post=function(node,p,page,ctx){
  if(!node?.org88SpecialHold)return org88PreviousOrg79Post(node,p,page,ctx);
  const person=state.personById.get(node.org88PersonId);
  const name=org76PersonName(person)||'زهرا ساطعی';
  return `<div class="org69-approved-post org79-approved-post org88-specialhold-post" data-post-id="${esc(node.id)}" style="left:${Math.round(p.x)}px;top:${Math.round(p.y)}px;width:${Math.round(p.w)}px"><div class="chart-node approved-node org88-specialhold-node" data-id="${esc(node.id)}" data-person="${esc(node.org88PersonId)}" style="width:${Math.round(p.w)}px;height:${Math.round(p.h)}px"><span class="org88-specialhold-kicker">${esc(node.org88Subtitle||'حفظ پست مرتبط')}</span><strong class="node-title" data-person="${esc(node.org88PersonId)}">${esc(name)}</strong><small>جانمایی مستقل زیر نود مرتبط</small></div></div>`;
};


/* v4.0.90 — compact textual breakdown with embedded coverage/vacancy KPIs,
   per-status gender split, and fully labelled pie segments. */
function org89StatusKey(person){
  if(!person)return'';
  if(person.named_post)return'breakdownNamed';
  if(person.outside_chart)return'breakdownOutside';
  if(person.is_hold_position)return'breakdownHold';
  const group=org76FaText(person.employment_group||'');
  if(group==='رسمی')return'breakdownFormal';
  if(group==='شرکتی')return'breakdownCompany';
  if(group==='حجمی')return'breakdownVolume';
  if(group==='پیمانکاری')return'breakdownContract';
  if(group==='مشاور')return'breakdownConsultant';
  return'';
}
function org89GenderByStatus(scopeKey){
  const out={};
  ['breakdownFormal','breakdownCompany','breakdownVolume','breakdownContract','breakdownConsultant','breakdownHold','breakdownNamed','breakdownOutside','breakdownNoPost'].forEach(k=>out[k]={female:0,male:0,unknown:0});
  (statusPeopleForScope(scopeKey)||[]).forEach(person=>{
    const key=org89StatusKey(person);if(!key||!out[key])return;
    const gender=org82GenderOf(person);
    if(gender==='female')out[key].female++;
    else if(gender==='male')out[key].male++;
    else out[key].unknown++;
  });
  return out;
}
function org89GenderText(counts){
  if(!counts)return'';
  const bits=[];
  if(counts.female)bits.push(`<span class="org89-mini-gender female">زن ${fa(counts.female)}</span>`);
  if(counts.male)bits.push(`<span class="org89-mini-gender male">مرد ${fa(counts.male)}</span>`);
  if(counts.unknown)bits.push(`<span class="org89-mini-gender unknown">نامشخص ${fa(counts.unknown)}</span>`);
  return bits.join('');
}
statusBreakdownTextPanel=function(data){
  const defs=[
    {key:'breakdownFormal',label:'رسمی',cls:'formal'},
    {key:'breakdownCompany',label:'شرکتی',cls:'company'},
    {key:'breakdownVolume',label:'حجمی',cls:'volume'},
    
    {key:'breakdownConsultant',label:'مشاور',cls:'consultant'},
    {key:'breakdownHold',label:'حفظ پست',cls:'hold'},
    {key:'breakdownNamed',label:'پست با نام',cls:'named'},
    {key:'breakdownOutside',label:'خارج چارت',cls:'outside'},
    {key:'emptyPosts',label:'پست خالی',cls:'empty'}
  ];
  const current=statusMetrics(state.statusScope);
  const source=(data&&data.length)?data:[{key:state.statusScope,label:scopeLabel(state.statusScope),metrics:current}];
  const columns=source.map(d=>{
    const m=d.metrics||statusMetrics(d.key),gender=org89GenderByStatus(d.key);
    const active=defs.map(x=>({...x,value:Number(m[x.key]||0)})).filter(x=>x.value>0);
    const rows=active.length?active.map(x=>{
      const genderBits=x.key==='emptyPosts'
        ?'<span class="org89-vacancy-note">جایگاه بدون متصدی</span>'
        :org89GenderText(gender[x.key]);
      return `<div class="org89-breakdown-row ${x.cls}" style="--status-color:${org82Colors[x.cls]||'#4f9cff'}"><div class="org89-breakdown-main"><i></i><strong>${esc(x.label)}</strong><b>${fa(x.value)}</b></div><div class="org89-breakdown-genders">${genderBits||'<span class="org89-mini-gender unknown">جنسیت ثبت نشده</span>'}</div></div>`;
    }).join(''):'<div class="org83-empty-breakdown">مورد ثبت‌شده‌ای برای نمایش وجود ندارد</div>';
    const unknown=m.unknownGender?`<small class="org89-unknown-total">جنسیت نامشخص: ${fa(m.unknownGender)}</small>`:'';
    return `<section class="status-breakdown-text-column org83-status-column org89-status-column"><header><strong>${esc(d.label)}</strong><small>ظرفیت ${fa(m.approved||0)} • نیروی فعلی ${fa(m.operational||0)}</small></header><div class="org89-status-list">${rows}</div><footer><span class="female">زن <b>${fa(m.female||0)}</b></span><span class="male">مرد <b>${fa(m.male||0)}</b></span>${unknown}</footer></section>`;
  }).join('');
  return `<aside class="status-breakdown-text-panel org82-column-breakdown org83-column-breakdown org89-column-breakdown"><div class="org82-breakdown-head org89-breakdown-head"><div><h4>تفکیک متنی وضعیت</h4><p>تعداد هر وضعیت همراه با تفکیک زن و مرد نمایش داده می‌شود.</p></div><span>مبنای نیروی فعلی: حوزه فعالیت</span></div><div class="org89-coverage-strip"><article class="coverage"><span>درصد پوشش فعلی</span><strong>${fa(current.currentPercent||0)}٪</strong><small>${fa(current.operational||0)} نیروی فعلی از ${fa(current.approved||0)} ظرفیت مصوب</small><i><em style="width:${Math.min(100,Number(current.currentPercent||0))}%"></em></i></article><article class="vacancy"><span>درصد پست‌های خالی</span><strong>${fa(current.emptyPercent||0)}٪</strong><small>${fa(current.emptyPosts||0)} پست خالی در این حوزه</small><i><em style="width:${Math.min(100,Number(current.emptyPercent||0))}%"></em></i></article></div><div class="status-breakdown-text-columns">${columns}</div></aside>`;
};

