function org89PieLabelBox(item,pct,x,y,side){
  const width=72,height=22,left=side==='right'?x:x-width;
  const dark=['#f5f7fa','#67e8f9','#c4b5fd'].includes(String(item.color||'').toLowerCase());
  return `<g class="org89-pie-callout"><rect x="${left}" y="${y-height/2}" width="${width}" height="${height}" rx="8" fill="rgba(7,20,33,.90)" stroke="${item.color}" stroke-width="1.2"/><circle cx="${side==='right'?left+9:left+width-9}" cy="${y}" r="3.2" fill="${item.color}"/><text x="${side==='right'?left+16:left+width-16}" y="${y+1}" text-anchor="${side==='right'?'start':'end'}" dominant-baseline="middle" class="org89-pie-callout-text${dark?' dark':''}">${esc(item.shortLabel||item.label)} ${fa(pct)}٪</text></g>`;
}
org84PieSvg=function(items){
  const active=(items||[]).filter(x=>Number(x.value||0)>0),total=Math.max(1,active.reduce((a,x)=>a+Number(x.value||0),0));
  const cx=180,cy=180,r=148;let angle=0;const sectors=[],largeLabels=[],small=[];
  active.forEach(item=>{
    const value=Number(item.value||0),span=value/total*360,start=angle,end=angle+span,mid=start+span/2,pct=Math.round(value/total*100);
    if(span>=359.999)sectors.push(`<circle cx="${cx}" cy="${cy}" r="${r}" fill="${item.color}" stroke="#071421" stroke-width="5"/>`);
    else sectors.push(`<path d="${org82PiePath(cx,cy,r,start,end)}" fill="${item.color}" stroke="#071421" stroke-width="5" stroke-linejoin="round"/>`);
    if(pct>=9){
      const lp=org82Polar(cx,cy,r*.58,mid),dark=['#f5f7fa','#67e8f9','#c4b5fd'].includes(String(item.color||'').toLowerCase());
      largeLabels.push(`<text x="${lp.x}" y="${lp.y-7}" text-anchor="middle" class="org89-pie-large-label${dark?' dark':''}">${esc(item.shortLabel||item.label)}</text><text x="${lp.x}" y="${lp.y+12}" text-anchor="middle" class="org89-pie-large-value${dark?' dark':''}">${fa(pct)}٪</text>`);
    }else{
      const anchor=org82Polar(cx,cy,r*.72,mid),right=mid>0&&mid<180;
      small.push({item,pct,mid,anchor,side:right?'right':'left'});
    }
    angle=end;
  });
  ['left','right'].forEach(side=>{
    const arr=small.filter(x=>x.side===side).sort((a,b)=>a.anchor.y-b.anchor.y);
    const minY=92,maxY=268,step=arr.length>1?(maxY-minY)/(arr.length-1):0;
    arr.forEach((x,i)=>{
      const y=arr.length===1?Math.max(minY,Math.min(maxY,x.anchor.y)):minY+i*step;
      const boxX=side==='right'?238:122;
      const lineEndX=side==='right'?238:122;
      sectors.push(`<path class="org89-pie-callout-line" d="M ${x.anchor.x.toFixed(1)} ${x.anchor.y.toFixed(1)} L ${lineEndX} ${y.toFixed(1)}" stroke="${x.item.color}" stroke-width="1.2" fill="none" opacity=".85"/>`);
      sectors.push(org89PieLabelBox(x.item,x.pct,boxX,y,side));
    });
  });
  if(!active.length)sectors.push(`<circle cx="${cx}" cy="${cy}" r="${r}" fill="#203247" stroke="#071421" stroke-width="5"/>`);
  return `<svg class="org83-pie-svg org84-pie-svg org89-pie-svg" viewBox="0 0 360 360" role="img" aria-label="نمودار ترکیب نیروی فعلی و پست‌های خالی"><circle cx="${cx}" cy="${cy}" r="${r+5}" fill="none" stroke="rgba(93,164,229,.20)" stroke-width="2"/>${sectors.join('')}${largeLabels.join('')}</svg>`;
};

