/* v4.0.98 — activity-first placement for every county employee.
   A structural root/unit may contain only its matching manager/head.
   Everyone else is placed in a valid descendant approved post, with
   current activity taking precedence over the recorded position title. */
function org98Structural(node,tree){
  return !!node&&(node.id===tree.root?.id||!!node.is_unit);
}
function org98DescendsFrom(nodeId,ancestorId,tree){
  let current=nodeId;
  for(let i=0;i<24&&current;i++){
    if(current===ancestorId)return true;
    current=tree.parent.get(current);
  }
  return false;
}
function org98CurrentNode(person,tree,page){
  const sheet=ORG97_ACTIVITY_POST_PLACEMENTS[person?.id];
  if(sheet&&+sheet.page===+page){
    if(tree.byId.has(sheet.nodeId))return tree.byId.get(sheet.nodeId);
    if(sheet.previousUnitNodeId&&tree.byId.has(sheet.previousUnitNodeId)){
      return tree.byId.get(sheet.previousUnitNodeId);
    }
  }
  const candidate=org77ActualCandidate(person);
  if(candidate&&tree.byId.has(candidate))return tree.byId.get(candidate);
  const structural=tree.nodes.filter(node=>org98Structural(node,tree));
  const source=`${person?.organizational_unit||''} ${person?.activity_area||''}`;
  return structural
    .map(node=>{
      const match=org94Overlap(source,node.text||'');
      return {node,score:match.coverage*3+match.jaccard*2+match.common};
    })
    .sort((a,b)=>b.score-a.score||String(a.node.text||'').localeCompare(String(b.node.text||''),'fa'))[0]?.node
    ||tree.root;
}
function org98ManagerScore(person,node){
  const position=org94Text(person?.position_title||'');
  if(!/(?:مدیر|مدير|مدیریت|مديريت|رئیس|رييس|رئيس|معاون|سرپرست)/.test(position))return -1;
  const title=org94Text(node?.text||'');
  const match=org94Overlap(position,title);
  let score=match.coverage*5+match.jaccard*3+match.common;
  if(position===title)score+=8;
  if(
    /(?:مدیر|مدير|مدیریت|مديريت)/.test(position)
    &&/(?:مدیر|مدير|مدیریت|مديريت|امور)/.test(title)
  )score+=2;
  if(
    /(?:رئیس|رييس|رئيس)/.test(position)
    &&/(?:اداره|دفتر|گروه|قسمت)/.test(title)
  )score+=2;
  if(/معاون/.test(position)&&/معاون/.test(title))score+=3;
  return score;
}
function org98PathText(node,tree){
  const parts=[];
  let current=node;
  for(let i=0;i<20&&current;i++){
    parts.push(current.text||'');
    current=tree.byId.get(tree.parent.get(current.id));
  }
  return parts.join(' ');
}
function org98SpecialScore(person,path,title){
  const source=org94Text(`${person?.activity_area||''} ${person?.position_title||''}`);
  const target=org94Text(`${path||''} ${title||''}`);
  let score=0;
  if(/(?:نگهبان|حراست|محرمانه|حفاظت)/.test(source)&&/(?:ایمنی|حریم|حراست|بحران|حفاظت)/.test(target))score+=8;
  if(/(?:مامور|مأمور).*(?:کنتور|قرائت|قطع|وصل|انشعاب)|(?:مشترک|اپراتور مشترکین)/.test(source)
    &&/(?:مشترک|فروش|وصول|انشعاب|کنتور|اندازه گیری|تست|بازرسی)/.test(target))score+=7;
  if(/(?:سیمبان|تعمیرات|نوسازی|کارگر چاله|اتفاقات|عملیات)/.test(source)
    &&/(?:فنی|تعمیرات|شبکه|بهره برداری|اتفاقات|عملیات|روستایی|سیمبان)/.test(target))score+=7;
  if(/(?:راننده|خودرو|نقلیه)/.test(source)
    &&/(?:فنی|بهره برداری|اتفاقات|عملیات|شبکه|روستایی|gis)/.test(target))score+=6;
  if(/(?:مالی|اداری|پشتیبانی|کارپرداز|تدارکات|انبار|دبیرخانه|فناوری|it)/.test(source)
    &&/(?:مالی|اداری|پشتیبانی|انبار|دبیرخانه|اطلاعات|نرم افزار|gis)/.test(target))score+=7;
  if(/(?:مهندسی|طراحی|نقشه|gis)/.test(source)
    &&/(?:مهندسی|طراحی|نقشه|gis|فنی|بهره برداری)/.test(target))score+=7;
  if(/(?:روشنایی|معابر)/.test(source)&&/(?:روشنایی|معابر|اتفاقات|عملیات)/.test(target))score+=8;
  return score;
}
function org98SemanticScore(person,node,tree,baseNode){
  const title=node?.text||'',path=org98PathText(node,tree);
  const position=org94PlacementScore(person,node);
  const activityMatch=org94Overlap(person?.activity_area||'',path);
  const positionMatch=org94Overlap(person?.position_title||'',title);
  const af=org94Family(person?.activity_area||'');
  const pf=org94Family(person?.position_title||'');
  const tf=org94Family(title);
  const pathFamily=org94Family(path);
  let score=position.score*4
    +activityMatch.coverage*5+activityMatch.jaccard*2+activityMatch.common*.7
    +positionMatch.coverage*3+positionMatch.jaccard*1.5+positionMatch.common*.5
    +org98SpecialScore(person,path,title);
  if(af&&af===tf)score+=5;
  if(af&&af===pathFamily)score+=4;
  if(pf&&pf===tf)score+=5;
  if(baseNode&&org98DescendsFrom(node.id,baseNode.id,tree))score+=2;
  return score;
}
function org98Target(person,tree,baseNode,out,groupTargets){
  let candidates=tree.nodes.filter(node=>!org98Structural(node,tree)&&!node.org88SpecialHold);
  if(baseNode&&org98Structural(baseNode,tree)){
    const local=candidates.filter(node=>org98DescendsFrom(node.id,baseNode.id,tree));
    if(local.length)candidates=local;
  }
  if(!candidates.length)return tree.root;
  const groupKey=[
    baseNode?.id||tree.root.id,
    org94Text(person?.activity_area||''),
    org94Text(person?.position_title||'')
  ].join('::');
  const remembered=groupTargets.get(groupKey);
  if(remembered&&tree.byId.has(remembered))return tree.byId.get(remembered);
  const ranked=candidates
    .map(node=>({
      node,
      score:org98SemanticScore(person,node,tree,baseNode),
      occupied:(out.get(node.id)||[]).filter(item=>(item.people||[]).length).length
    }))
    .sort((a,b)=>b.score-a.score||a.occupied-b.occupied||String(a.node.text||'').localeCompare(String(b.node.text||''),'fa'));
  const bestScore=ranked[0]?.score||0;
  const close=ranked.filter(item=>item.score>=bestScore-.75);
  close.sort((a,b)=>(a.occupied>0)-(b.occupied>0)||a.occupied-b.occupied||b.score-a.score
    ||String(a.node.text||'').localeCompare(String(b.node.text||''),'fa'));
  const chosen=(close[0]||ranked[0]).node;
  groupTargets.set(groupKey,chosen.id);
  return chosen;
}
function org98Card(person,target){
  const hold=!!person?.is_hold_position;
  return {
    ...org77ActualItem(person,target),
    kind:hold?'hold':org94EmploymentKind(person),
    label:hold?'حفظ پست':org76FaText(person?.employment_group||'نوع استخدام نامشخص'),
    rank:hold?30:org94EmploymentRank(person),
    org77Note:'',
    org94MergedHold:hold,
    org94PendingHold:false,
    org98ActivityPlaced:true
  };
}
const org98PreviousOrg79Cards=org79Cards;
org79Cards=function(type,page,slide){
  if(!org94CountyPage(page)||org77Mode(type)!=='actual'){
    return org98PreviousOrg79Cards(type,page,slide);
  }
  const tree=org79Tree(type,+page,slide);
  if(!tree?.root)return org98PreviousOrg79Cards(type,page,slide);
  const out=new Map(tree.nodes.map(node=>[node.id,[]]));
  const expected=state.people.filter(person=>person&&+(
    ORG97_ACTIVITY_POST_PLACEMENTS[person.id]?.page||org77ActualPage(person)
  )===+page);
  const entries=expected.map(person=>({
    person,
    current:org98CurrentNode(person,tree,+page)
  }));
  const managerByNode=new Map();
  tree.nodes.filter(node=>org98Structural(node,tree)).forEach(node=>{
    const ranked=entries
      .filter(entry=>entry.current?.id===node.id)
      .map(entry=>({entry,score:org98ManagerScore(entry.person,node)}))
      .filter(item=>item.score>=3)
      .sort((a,b)=>b.score-a.score||String(org76PersonName(a.entry.person)).localeCompare(String(org76PersonName(b.entry.person)),'fa'));
    if(ranked[0])managerByNode.set(node.id,ranked[0].entry.person.id);
  });
  const unresolved=[];
  const audit=[];
  entries.forEach(entry=>{
    const {person,current}=entry;
    if(current&&org98Structural(current,tree)&&managerByNode.get(current.id)===person.id){
      out.get(current.id).push(org98Card(person,current));
      audit.push({personId:person.id,from:current.id,to:current.id,status:'manager'});
      return;
    }
    if(current&&!org98Structural(current,tree)&&tree.byId.has(current.id)){
      out.get(current.id).push(org98Card(person,current));
      audit.push({personId:person.id,from:current.id,to:current.id,status:'approved-post'});
      return;
    }
    unresolved.push(entry);
  });
  const groupTargets=new Map();
  unresolved
    .sort((a,b)=>String(org76PersonName(a.person)).localeCompare(String(org76PersonName(b.person)),'fa'))
    .forEach(({person,current})=>{
      const target=org98Target(person,tree,current,out,groupTargets);
      out.get(target.id).push(org98Card(person,target));
      audit.push({
        personId:person.id,
        from:current?.id||'',
        to:target.id,
        status:'activity-post',
        activity:org76FaText(person.activity_area||''),
        position:org76FaText(person.position_title||'')
      });
    });
  tree.nodes.forEach(node=>{
    const items=out.get(node.id)||[];
    if(!items.length&&!org98Structural(node,tree)&&!node.org88SpecialHold){
      items.push(org94EmptyCard(node));
    }
    items.sort((a,b)=>(a.rank-b.rank)||String(a.main||'').localeCompare(String(b.main||''),'fa'));
    out.set(node.id,items);
  });
  const renderedPeople=[...out.values()].flatMap(items=>(items||[]).flatMap(item=>item.people||[]));
  const renderedIds=new Set(renderedPeople.map(person=>person.id));
  const structuralPeople=tree.nodes
    .filter(node=>org98Structural(node,tree))
    .flatMap(node=>(out.get(node.id)||[]).flatMap(item=>item.people||[]));
  window.__ORG98_COUNTY_AUDIT__=window.__ORG98_COUNTY_AUDIT__||{};
  window.__ORG98_COUNTY_AUDIT__[String(+page)]={
    page:+page,
    title:slide?.title||'',
    expected:expected.length,
    rendered:renderedPeople.length,
    unique:renderedIds.size,
    missing:expected.filter(person=>!renderedIds.has(person.id)).map(person=>person.id),
    managers:[...managerByNode.values()],
    structuralPeople:structuralPeople.map(person=>person.id),
    movedToPosts:audit.filter(item=>item.status==='activity-post').length,
    maxColumn:Math.max(0,...tree.nodes.map(node=>(out.get(node.id)||[]).filter(item=>(item.people||[]).length).length)),
    merged:expected.filter(person=>person.is_hold_position).length,
    review:0,
    items:audit
  };
  window.__ORG94_COUNTY_AUDIT__=window.__ORG94_COUNTY_AUDIT__||{};
  window.__ORG94_COUNTY_AUDIT__[String(+page)]=window.__ORG98_COUNTY_AUDIT__[String(+page)];
  return out;
};
const org98PreviousOrg79Metrics=org79Metrics;
org79Metrics=function(node,cards,ctx){
  const metrics=org98PreviousOrg79Metrics(node,cards,ctx);
  if(!org94CountyPage(org94NodePage(node)))return metrics;
  return {
    ...metrics,
    isRoot:node.id===ctx.root.id,
    isUnit:node.id===ctx.root.id||!!node.is_unit
  };
};
const org98PreviousFitChart=fitChart;
fitChart=function(type){
  const {canvas,stage,shell}=chartDom(type);
  if(!canvas?.classList?.contains('org94-county-canvas'))return org98PreviousFitChart(type);
  if(!stage||!shell)return;
  const cfg=state.chart[type]||(state.chart[type]={zoomFactor:1,fitScale:1,manual:false});
  canvas.style.setProperty('transform','none','important');
  canvas.style.left='0';canvas.style.top='0';
  const bounds=chartContentBounds(canvas),cs=getComputedStyle(stage);
  const padL=parseFloat(cs.paddingLeft)||0,padR=parseFloat(cs.paddingRight)||0;
  const padT=parseFloat(cs.paddingTop)||0,padB=parseFloat(cs.paddingBottom)||0;
  const availW=Math.max(320,stage.clientWidth-padL-padR-18);
  const availH=Math.max(360,stage.clientHeight-padT-padB-18);
  const widthFit=availW/bounds.width;
  const heightFit=availH/bounds.height;
  const naturallyCompact=bounds.height<=availH*1.35;
  let fit=naturallyCompact?Math.min(widthFit,heightFit):widthFit;
  if(!isFinite(fit)||fit<=0)fit=1;
  fit=Math.max(.58,Math.min(.98,fit));
  if(!cfg.manual)cfg.zoomFactor=1;
  cfg.fitScale=fit;
  const scale=fit*(cfg.zoomFactor||1),pad=10;
  const visualW=bounds.width*scale+pad*2,visualH=bounds.height*scale+pad*2;
  shell.style.width=Math.ceil(visualW)+'px';
  shell.style.height=Math.ceil(visualH)+'px';
  shell.style.marginLeft=Math.max(0,Math.floor((availW-visualW)/2))+'px';
  shell.style.marginTop='0';shell.style.marginRight='0';shell.style.marginBottom='20px';
  canvas.style.setProperty('transform-origin','0 0','important');
  canvas.style.setProperty('transform',`translate(${pad-bounds.minX*scale}px,${pad-bounds.minY*scale}px) scale(${scale})`,'important');
  stage.style.overflow='auto';
  stage.scrollTop=0;
  requestAnimationFrame(()=>{
    stage.scrollLeft=Math.max(0,Math.floor((stage.scrollWidth-stage.clientWidth)/2));
    stage.scrollTop=0;
  });
  canvas.dataset.fitScale=String(scale);
  canvas.dataset.fitBounds=JSON.stringify(bounds);
  canvas.dataset.fitPolicy='readable-width-first-for-tall-vertical-stacks';
  updateChartControls(type,scale);
};
const org98PreviousRenderChart=renderChart;
renderChart=function(type,page){
  org98PreviousRenderChart(type,page);
  if(!org94CountyPage(page))return;
  const {canvas}=chartDom(type);if(!canvas)return;
  canvas.dataset.layoutVersion='4.0.98';
  canvas.dataset.layoutPolicy='current-activity-first+valid-approved-post+vertical-stack+manager-only-structural-node';
  canvas.dataset.structuralPolicy='manager-only';
  canvas.dataset.vacancyPolicy='prefer-related-empty-post';
  canvas.dataset.unmatchedPolicy='no-general-list';
  scheduleChartFit(type);
};

/* v4.0.99 — source-audited county placement.
   The placement map is generated from the reference Sheet1 data and the
   approved chart skeleton. No person is forced into an unrelated approved
   post: unresolved roles receive a clearly-labelled current-placement node. */
const ORG99_VERIFIED_MODEL=window.SazmanHRPlacementModels.ORG99_VERIFIED_MODEL;

function org99CountyPage(page){
  page=+page;
  return page>=21&&page<=53;
}

const org99PreviousTree=org79Tree;
org79Tree=function(type,page,slide){
  const tree=org99PreviousTree(type,page,slide);
  if(!tree||!org99CountyPage(page)||org77Mode(type)!=='actual')return tree;
  const pageModel=ORG99_VERIFIED_MODEL.pages[String(+page)];
  if(!pageModel)return tree;
  (pageModel.extraNodes||[]).forEach(spec=>{
    if(tree.byId.has(spec.id))return;
    const parentId=tree.byId.has(spec.parentId)?spec.parentId:tree.root.id;
    const node={
      id:spec.id,
      text:spec.text,
      page:+page,
      count:1,
      is_unit:false,
      org99ActualGroup:true,
      org99Reason:spec.reason||'فاقد پست مصوب متناظر'
    };
    tree.nodes.push(node);
    tree.byId.set(node.id,node);
    tree.parent.set(node.id,parentId);
    tree.children.set(node.id,[]);
    const siblings=tree.children.get(parentId)||[];
    siblings.push(node);
    tree.children.set(parentId,siblings);
  });
  return tree;
};

function org99Card(person,target,placement){
  const card=org98Card(person,target);
  card.org99PlacementStatus=placement.status||'';
  card.org99PlacementReason=placement.reason||'';
  if(target?.org99ActualGroup){
    card.org99ActualOnly=true;
    card.label='استقرار فعلی';
    card.rank=35;
  }
  return card;
}

const org99PreviousCards=org79Cards;
org79Cards=function(type,page,slide){
  if(!org99CountyPage(page)||org77Mode(type)!=='actual'){
    return org99PreviousCards(type,page,slide);
  }
  const pageModel=ORG99_VERIFIED_MODEL.pages[String(+page)];
  const tree=org79Tree(type,+page,slide);
  if(!pageModel||!tree?.root)return org99PreviousCards(type,page,slide);
  const out=new Map(tree.nodes.map(node=>[node.id,[]]));
  const audit=[];
  (pageModel.placements||[]).forEach(placement=>{
    const person=state.personById.get(placement.personId);
    if(!person)return;
    const target=tree.byId.get(placement.nodeId)||tree.root;
    out.get(target.id).push(org99Card(person,target,placement));
    audit.push({
      personId:person.id,
      to:target.id,
      status:placement.status,
      reason:placement.reason,
      sourceUnit:placement.sourceUnit||'',
      sourceActivity:placement.sourceActivity||'',
      sourcePosition:placement.sourcePosition||''
    });
  });
  tree.nodes.forEach(node=>{
    const items=out.get(node.id)||[];
    if(
      !items.length
      &&!org98Structural(node,tree)
      &&!node.org88SpecialHold
      &&!node.org99ActualGroup
    ){
      items.push(org94EmptyCard(node));
    }
    items.sort((a,b)=>(a.rank-b.rank)||String(a.main||'').localeCompare(String(b.main||''),'fa'));
    out.set(node.id,items);
  });
  const expected=(pageModel.placements||[])
    .map(item=>state.personById.get(item.personId))
    .filter(Boolean);
  const rendered=[...out.values()].flatMap(items=>(items||[]).flatMap(item=>item.people||[]));
  const ids=rendered.map(person=>person.id),unique=new Set(ids);
  const structuralPeople=tree.nodes
    .filter(node=>org98Structural(node,tree))
    .flatMap(node=>(out.get(node.id)||[]).flatMap(item=>item.people||[]));
  const summary={
    page:+page,
    title:slide?.title||'',
    expected:expected.length,
    rendered:rendered.length,
    unique:unique.size,
    missing:expected.filter(person=>!unique.has(person.id)).map(person=>person.id),
    managers:audit.filter(item=>item.status==='manager').map(item=>item.personId),
    structuralPeople:structuralPeople.map(person=>person.id),
    movedToPosts:audit.filter(item=>item.status==='approved-exact'||item.status==='approved-related').length,
    actualOnly:audit.filter(item=>item.status==='actual-only').length,
    maxColumn:Math.max(0,...tree.nodes.map(node=>(out.get(node.id)||[]).filter(item=>(item.people||[]).length).length)),
    merged:expected.filter(person=>person.is_hold_position).length,
    review:0,
    items:audit
  };
  window.__ORG99_COUNTY_AUDIT__=window.__ORG99_COUNTY_AUDIT__||{};
  window.__ORG99_COUNTY_AUDIT__[String(+page)]=summary;
  window.__ORG94_COUNTY_AUDIT__=window.__ORG94_COUNTY_AUDIT__||{};
  window.__ORG94_COUNTY_AUDIT__[String(+page)]=summary;
  return out;
};

const org99PreviousPost=org79Post;
org79Post=function(node,p,page,ctx){
  let html=org99PreviousPost(node,p,page,ctx);
  if(!node?.org99ActualGroup)return html;
  return html
    .replace('org94-county-post','org94-county-post org99-actual-group-post')
    .replace('<span class="node-status">استقرار واقعی</span>','<span class="node-status org99-actual-status">جایگاه فعلی؛ فاقد پست مصوب متناظر</span>');
};

const org99PreviousRenderChart=renderChart;
renderChart=function(type,page){
  org99PreviousRenderChart(type,page);
  if(!org99CountyPage(page))return;
  const {canvas}=chartDom(type);
  if(!canvas)return;
  canvas.dataset.layoutVersion='4.0.99';
  canvas.dataset.layoutPolicy='source-audited+approved-when-compatible+explicit-actual-only+vertical-stack';
  canvas.dataset.sourcePolicy='Sheet1-authoritative-for-county-unit-location-activity-position';
  canvas.dataset.unmatchedPolicy='explicit-current-placement-node;never-unrelated-approved-post';
  scheduleChartFit(type);
};

/* v4.1.01 — reviewed placement of every former needs-decision person.
   Approved posts are used when the evidence supports them. When the county
   chart has no corresponding approved post, the person is attached to a
   clearly named operational branch under the correct approved area. */
const ORG101_VERIFIED_MODEL=window.SazmanHRPlacementModels.ORG101_VERIFIED_MODEL;

function org101CountyPage(page){
  page=+page;
  return page>=21&&page<=53;
}

function org101RemoveNode(tree,node){
  const parentId=tree.parent.get(node.id);
  if(parentId&&tree.children.has(parentId)){
    tree.children.set(
      parentId,
      (tree.children.get(parentId)||[]).filter(child=>(child?.id||child)!==node.id)
    );
  }
  tree.byId.delete(node.id);
  tree.parent.delete(node.id);
  tree.children.delete(node.id);
}

const org101PreviousTree=org79Tree;
org79Tree=function(type,page,slide){
  const tree=org101PreviousTree(type,page,slide);
  if(!tree||!org101CountyPage(page)||org77Mode(type)!=='actual')return tree;

  /* Remove every synthetic group from the previous county placement pass. */
  const obsolete=tree.nodes.filter(node=>node?.org99ActualGroup||node?.org100ReviewGroup);
  obsolete.forEach(node=>org101RemoveNode(tree,node));
  tree.nodes=tree.nodes.filter(node=>!node?.org99ActualGroup&&!node?.org100ReviewGroup);

  const pageModel=ORG101_VERIFIED_MODEL.pages[String(+page)];
  (pageModel?.operationalNodes||[]).forEach(spec=>{
    if(tree.byId.has(spec.id))return;
    const parentId=tree.byId.has(spec.parentId)?spec.parentId:tree.root.id;
    const node={
      id:spec.id,
      text:spec.text,
      page:+page,
      count:1,
      is_unit:false,
      org101OperationalGroup:true,
      org101Domain:spec.domain||'',
      org101Evidence:spec.evidence||''
    };
    tree.nodes.push(node);
    tree.byId.set(node.id,node);
    tree.parent.set(node.id,parentId);
    tree.children.set(node.id,[]);
    const siblings=tree.children.get(parentId)||[];
    siblings.push(node);
    tree.children.set(parentId,siblings);
  });
  return tree;
};

function org101Card(person,target,placement){
  const card=org98Card(person,target);
  card.org101PlacementStatus=placement.status||'';
  card.org101PlacementReason=placement.reason||'';
  if(target?.org101OperationalGroup){
    card.org101OperationalRelated=true;
    card.label='حوزهٔ مرتبط — خارج از پست مصوب';
    card.rank=34;
  }
  return card;
}

