org79Cards=function(type,page,slide){
  if(!org101CountyPage(page)||org77Mode(type)!=='actual'){
    return org101PreviousCards(type,page,slide);
  }
  const pageModel=ORG101_VERIFIED_MODEL.pages[String(+page)];
  const tree=org79Tree(type,+page,slide);
  if(!pageModel||!tree?.root)return org101PreviousCards(type,page,slide);

  const out=new Map(tree.nodes.map(node=>[node.id,[]]));
  const audit=[];
  (pageModel.placements||[]).forEach(placement=>{
    const person=state.personById.get(placement.personId);
    if(!person)return;
    const target=tree.byId.get(placement.nodeId);
    if(!target)return;
    out.get(target.id).push(org101Card(person,target,placement));
    audit.push({
      personId:person.id,
      to:target.id,
      status:placement.status,
      reason:placement.reason,
      sourceActivity:placement.sourceActivity||'',
      sourcePosition:placement.sourcePosition||''
    });
  });

  tree.nodes.forEach(node=>{
    const items=out.get(node.id)||[];
    if(
      !items.length
      &&!org98Structural(node,tree)
      &&!node.org88SpecialHold
      &&!node.org101OperationalGroup
    ){
      items.push(org94EmptyCard(node));
    }
    items.sort((a,b)=>(a.rank-b.rank)||String(a.main||'').localeCompare(String(b.main||''),'fa'));
    out.set(node.id,items);
  });

  const expected=(pageModel.placements||[])
    .map(item=>state.personById.get(item.personId))
    .filter(Boolean);
  const rendered=[...out.values()].flatMap(items=>(items||[]).flatMap(item=>item.people||[]));
  const ids=rendered.map(person=>person.id);
  const unique=new Set(ids);
  const structuralPeople=tree.nodes
    .filter(node=>org98Structural(node,tree))
    .flatMap(node=>(out.get(node.id)||[]).flatMap(item=>item.people||[]));
  const summary={
    page:+page,
    title:slide?.title||'',
    expected:expected.length,
    rendered:rendered.length,
    unique:unique.size,
    missing:expected.filter(person=>!unique.has(person.id)).map(person=>person.id),
    managers:audit.filter(item=>item.status==='manager').map(item=>item.personId),
    structuralPeople:structuralPeople.map(person=>person.id),
    matchedToApproved:audit.filter(item=>item.status!=='manager'&&item.status!=='operational-related').length,
    operationalRelated:audit.filter(item=>item.status==='operational-related').length,
    needsDecision:0,
    vacancies:(pageModel.vacancies||[]).filter(item=>item.vacant).length,
    maxColumn:Math.max(
      0,
      ...tree.nodes.map(node=>(out.get(node.id)||[]).filter(item=>(item.people||[]).length).length)
    ),
    merged:expected.filter(person=>person.is_hold_position).length,
    review:0,
    items:audit
  };
  window.__ORG101_COUNTY_AUDIT__=window.__ORG101_COUNTY_AUDIT__||{};
  window.__ORG101_COUNTY_AUDIT__[String(+page)]=summary;
  window.__ORG100_COUNTY_AUDIT__=window.__ORG100_COUNTY_AUDIT__||{};
  window.__ORG100_COUNTY_AUDIT__[String(+page)]=summary;
  window.__ORG94_COUNTY_AUDIT__=window.__ORG94_COUNTY_AUDIT__||{};
  window.__ORG94_COUNTY_AUDIT__[String(+page)]=summary;
  return out;
};

