function org111ScopePages(key='company'){
  key=String(key||'company');
  const all=Object.keys(ORG111_STATUS_VACANCY_BY_PAGE).map(Number);
  if(key==='company'||key==='slide:1'||key==='slide:2')return new Set(all);
  if(key==='direct:company')return new Set([2]);
  if(key.startsWith('direct:slide:'))return new Set([+key.split(':')[2]]);
  if(key.startsWith('slide:'))return new Set([...routeDescendantPages(+key.split(':')[1])].filter(p=>ORG111_STATUS_VACANCY_BY_PAGE[String(+p)]));
  if(key.startsWith('node:')){
    const n=state.nodeById.get(key.slice(5));
    const target=n?routeTarget(n.page,n.text):0;
    if(target)return new Set([...routeDescendantPages(target)].filter(p=>ORG111_STATUS_VACANCY_BY_PAGE[String(+p)]));
    return new Set(n?.page?[+n.page]:[]);
  }
  return new Set();
}
function org111VacancyAuditForScope(key='company'){
  const pages=org111ScopePages(key),out={pages:[...pages].sort((a,b)=>a-b),auditedPosts:0,vacantPosts:0,occupiedAuditedPosts:0,multiOccupantPosts:0,occupantAssignments:0};
  pages.forEach(page=>{const row=ORG111_STATUS_VACANCY_BY_PAGE[String(+page)];if(!row)return;Object.keys(row).forEach(k=>out[k]=(out[k]||0)+Number(row[k]||0));});
  return out;
}
const org111PreviousApprovedCapacityForScope=approvedCapacityForScope;
