  let value=!!p.is_hold_position;if(!value&&org112HasApprovedPost(p)){const approved=org112ApprovedPage(p),current=org112StatusPrimaryPage(p);value=!!(approved&&current&&approved!==current)}
  cache?.set(key,value);return value;
