  const pages=org111ScopePages(key);return (ORG112_VACANCY_AUDIT||[]).filter(r=>pages.has(Number(r.page))).map(r=>{const valid=(r.occupants||[]).filter(o=>{const p=state.personById.get(o.id);return p&&org112RawPlacementPage(p)===Number(r.page)});return {...r,validOccupants:valid,validCount:valid.length,scopeLabel:getSlide(r.page)?.title||r.pageTitle||`صفحه ${r.page}`}}).filter(r=>kind==='all'||(kind==='occupied'&&r.validCount>0)||(kind==='single'&&r.validCount===1)||(kind==='multi'&&r.validCount>1)||(kind==='empty'&&r.validCount===0));
