function org115RenderQualityRanking(children){const rows=(children.length?children:[{key:state.statusScope,label:scopeLabel(state.statusScope)}]).map(x=>({...x,q:org115QualityForScope(x.key)})).sort((a,b)=>b.q.overall-a.q.overall).slice(0,7);$('#statusQualityRanking').innerHTML=rows.map(x=>`<div class="org115-quality-rank"><button data-status-scope="${esc(x.key)}">${esc(x.label)}</button><div class="track"><i style="width:${x.q.overall}%"></i></div><b>${fa(x.q.overall)}٪</b></div>`).join('');$('#statusQualityRanking').querySelectorAll('[data-status-scope]').forEach(b=>b.onclick=()=>openStatusScope(b.dataset.statusScope))}
function org115IssueRows(q){const d=q.issues,defs=[['شماره پرسنلی تکراری',d.duplicates,'بحرانی',org115Colors.red],['شماره پرسنلی خالی',d.missingNo,'بحرانی',org115Colors.red],['نام ناقص',d.missingName,'هشدار',org115Colors.orange],['محل فعالیت ناقص',d.missingLocation,'هشدار',org115Colors.orange],['گروه استخدامی نامعتبر',d.invalidGroup,'هشدار',org115Colors.orange],['استقرار نامعتبر',d.invalidPlacement,'نیازمند بررسی',org115Colors.red],['مغایرت پست خالی',d.vacancyMismatch,'نیازمند بررسی',org115Colors.purple]];const nonzero=defs.filter(x=>x[1]>0);return nonzero.length?nonzero: [['هیچ مغایرت بحرانی ثبت نشده',0,'وضعیت مطلوب',org115Colors.green]]}
