function org115TableRowStatus(m){if(m.currentPercent>=90)return['عالی',org115Colors.green];if(m.currentPercent>=80)return['خوب',org115Colors.cyan];if(m.currentPercent>=70)return['متوسط',org115Colors.orange];return['نیازمند توجه',org115Colors.red]}
