function org115FilteredRows(){let rows=org115TableState.rows.slice(),q=org115TableState.query.trim();if(q)rows=rows.filter(x=>x.label.includes(q));if(org115TableState.filter==='vacancy')rows=rows.filter(x=>x.metrics.emptyPosts>0);if(org115TableState.filter==='hold')rows=rows.filter(x=>x.metrics.breakdownHold>0);if(org115TableState.filter==='low')rows=rows.filter(x=>x.metrics.currentPercent<80);const sort=org115TableState.sort,desc=(k)=>rows.sort((a,b)=>b.metrics[k]-a.metrics[k]),asc=(k)=>rows.sort((a,b)=>a.metrics[k]-b.metrics[k]);if(sort==='occupancy-desc')desc('currentPercent');else if(sort==='occupancy-asc')asc('currentPercent');else if(sort==='vacancy-desc')desc('emptyPosts');else if(sort==='hold-desc')desc('breakdownHold');else if(sort==='people-desc')desc('operational');return rows}
