function org115RenderTableRows(){const all=org115FilteredRows(),pages=Math.max(1,Math.ceil(all.length/org115TableState.pageSize));org115TableState.page=Math.min(org115TableState.page,pages);const start=(org115TableState.page-1)*org115TableState.pageSize,rows=all.slice(start,start+org115TableState.pageSize),host=$('#statusTable');const cell=(kind,val,key,cls='')=>`<td class="${cls}"><button type="button" class="org112-table-number" data-status-detail="${kind}" data-status-scope-key="${esc(key)}">${fa(val)}</button></td>`;host.innerHTML=`<table><thead><tr><th>واحد</th><th>پست مصوب</th><th>پست پر</th><th>پست خالی</th><th>درصد اشغال</th><th>نیروی فعلی</th><th>حفظ پست</th><th>رسمی</th><th>شرکتی</th><th>حجمی</th><th>مشاور</th><th>وضعیت</th></tr></thead><tbody>${rows.map(x=>{const m=x.metrics,[status,color]=org115TableRowStatus(m),occCls=m.currentPercent<70?'bad':m.currentPercent<85?'warn':'';return`<tr data-status-scope="${esc(x.key)}"><td><b>${esc(x.label)}</b></td><td>${fa(m.approved)}</td><td><button type="button" class="org112-table-number" data-org115-post-kind="occupied" data-org115-scope="${esc(x.key)}">${fa(m.occupiedPosts)}</button></td>${cell('empty',m.emptyPosts,x.key,'org112-empty-cell')}<td><span class="org115-occupancy-pill ${occCls}">${fa(m.currentPercent)}٪</span></td>${cell('all',m.operational,x.key)}${cell('hold',m.breakdownHold,x.key,'org112-hold-cell')}${cell('formal',m.breakdownFormal,x.key)}${cell('company',m.breakdownCompany,x.key)}${cell('volume',m.breakdownVolume,x.key)}${cell('contract',m.breakdownContract,x.key)}${cell('consultant',m.breakdownConsultant,x.key)}<td><span class="status-result" style="border-color:${color};color:${color}">${status}</span></td></tr>`}).join('')||'<tr><td colspan="13">واحدی مطابق فیلتر فعلی پیدا نشد.</td></tr>'}</tbody></table>`;host.querySelectorAll('tr[data-status-scope]').forEach(r=>r.onclick=()=>openStatusScope(r.dataset.statusScope));org112BindDetailTriggers(host);org115BindPostDetails(host);$('#org115TablePager').innerHTML=`<span>نمایش ${fa(all.length?start+1:0)} تا ${fa(Math.min(start+org115TableState.pageSize,all.length))} از ${fa(all.length)} واحد</span><div><button id="org115Prev" type="button" ${org115TableState.page<=1?'disabled':''}>قبلی</button> <b>${fa(org115TableState.page)} / ${fa(pages)}</b> <button id="org115Next" type="button" ${org115TableState.page>=pages?'disabled':''}>بعدی</button></div>`;const prev=$('#org115Prev'),next=$('#org115Next');if(prev)prev.onclick=()=>{org115TableState.page--;org115RenderTableRows()};if(next)next.onclick=()=>{org115TableState.page++;org115RenderTableRows()}}
renderStatusTable=function(children){const rows=children.length?children:[{key:state.statusScope,label:scopeLabel(state.statusScope),metrics:statusMetrics()}];org115TableState.rows=rows;org115TableState.page=1;org115RenderTableSummary(rows,statusMetrics());org115RenderUnitRanking(rows);org115RenderTableRows();const search=$('#org115TableSearch'),sort=$('#org115TableSort');if(search){search.value='';search.oninput=()=>{org115TableState.query=search.value;org115TableState.page=1;org115RenderTableRows()}}if(sort){sort.value=org115TableState.sort;sort.onchange=()=>{org115TableState.sort=sort.value;org115TableState.page=1;org115RenderTableRows()}}document.querySelectorAll('[data-org115-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-org115-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');org115TableState.filter=b.dataset.org115Filter;org115TableState.page=1;org115RenderTableRows()})}
