function org116PctText(v,total){return `${fa(org115Pct(v,total))}٪`}
function org116KpiCard({title,value,sub,color,icon,kind='',suffix='',meter=0,postKind=''}){const clickable=!!(kind||postKind),tag=clickable?'button':'article',attrs=kind?` data-status-detail="${kind}" data-status-scope-key="${esc(state.statusScope)}"`:postKind?` data-org115-post-kind="${postKind}" data-org115-scope="${esc(state.statusScope)}"`:'';const gender=kind&&kind!=='empty'?org116GenderBadges(org116GenderForKind(kind),true):'';return `<${tag}${clickable?' type="button"':''} class="org115-kpi-card${clickable?' clickable':''}" style="--c:${color}"${attrs}><div class="top"><h3>${esc(title)}</h3><span class="icon">${icon}</span></div><strong>${fa(value)}${suffix}</strong><p>${esc(sub)}</p>${gender}<div class="meter"><i style="width:${org115Clamp(meter)}%"></i></div>${clickable?'<em>مشاهده جزئیات ←</em>':''}</${tag}>`}
org115KpiCard=org116KpiCard;
org115AnalysisTile=function(title,value,sub,color,meter){const shown=typeof value==='string'?esc(value):org116Num(value);return `<article class="org115-analysis-tile" style="--c:${color}"><span>${esc(title)}</span><strong>${shown}</strong><small>${esc(sub)}</small><div class="tiny-meter"><i style="width:${org115Clamp(meter)}%"></i></div></article>`};
function org116EmploymentCard(kind,label,value,total,color,letter){const pct=org115Pct(value,total),g=org116GenderForKind(kind);return `<button type="button" class="org115-employment-card org116-person-card" style="--c:${color}" data-status-detail="${kind}" data-status-scope-key="${esc(state.statusScope)}"><div class="head"><span>${esc(label)}</span><b class="letter">${letter}</b></div><div class="org116-card-number"><strong>${org116Num(value)}</strong><i>${org116Num(pct)}٪</i></div>${org116GenderBadges(g,true)}<small>از نیروی یکتای همین حوزه</small><div class="bar"><i style="width:${pct}%"></i></div><em>مشاهده اسامی ←</em></button>`}
org115EmploymentCard=org116EmploymentCard;
function org116SpecialCard(kind,label,value,total,color,letter,desc){const pct=org115Pct(value,total),g=org116GenderForKind(kind);return `<button type="button" class="org116-special-card" style="--c:${color}" data-status-detail="${kind}" data-status-scope-key="${esc(state.statusScope)}" data-count="${value}" data-male="${g.male}" data-female="${g.female}" data-unknown="${g.unknown}"><div class="head"><span>${esc(label)}</span><b>${letter}</b></div><div class="org116-card-number"><strong>${org116Num(value)}</strong><i>${org116Num(pct)}٪</i></div>${org116GenderBadges(g,true)}<small>${esc(desc)}</small><em>مشاهده افراد ←</em></button>`}
function org115RenderPrimaryKpis(m){$('#statusKpis').innerHTML=[
 org116KpiCard({title:'ظرفیت مصوب',value:m.approved,sub:'کل پست‌های ساختاری یکتای این حوزه',color:org115Colors.blue,icon:'⌘',meter:100,postKind:'all'}),
 org116KpiCard({title:'نیروی فعلی یکتا',value:m.operational,sub:`نسبت نفر به ظرفیت: ${fa(m.personnelLoadPercent)}٪`,color:org115Colors.cyan,icon:'◉',meter:Math.min(100,m.personnelLoadPercent),kind:'all'}),
 org116KpiCard({title:'پست دارای متصدی',value:m.occupiedPosts,sub:`${fa(m.currentPercent)}٪ از ظرفیت مصوب`,color:org115Colors.green,icon:'✓',meter:m.currentPercent,postKind:'occupied'}),
 org116KpiCard({title:'پست خالی واقعی',value:m.emptyPosts,sub:`${fa(m.emptyPercent)}٪ از ظرفیت مصوب`,color:org115Colors.red,icon:'×',meter:m.emptyPercent,kind:'empty'}),
 org116KpiCard({title:'درصد اشغال',value:m.currentPercent,suffix:'٪',sub:'پست دارای متصدی ÷ پست مصوب',color:m.currentPercent>=80?org115Colors.green:org115Colors.orange,icon:'%',meter:m.currentPercent}),
 org116KpiCard({title:'حفظ پست',value:m.breakdownHold,sub:'پست مصوب مبدأ متفاوت از استقرار فعلی',color:org115Colors.orange,icon:'H',meter:org115Pct(m.breakdownHold,m.operational),kind:'hold'})
 ].join('')}
function org116Arc(cx,cy,r,start,end){return org115ArcPath(cx,cy,r,start,end)}
function org116RenderWorkforceChart(m){const host=$('#statusWorkforceChart');if(!host)return;const total=Math.max(1,m.operational),employment=[
 {kind:'formal',label:'رسمی',value:m.breakdownFormal,color:org115Colors.green},
 {kind:'company',label:'شرکتی',value:m.breakdownCompany,color:org115Colors.white},
 {kind:'volume',label:'حجمی',value:m.breakdownVolume,color:org115Colors.purple},
 
 {kind:'consultant',label:'مشاور',value:m.breakdownConsultant,color:org115Colors.rose}
 ],special=[
 {kind:'hold',label:'حفظ پست',value:m.breakdownHold,color:org115Colors.orange,r:91},
 {kind:'named',label:'پست با نام',value:m.breakdownNamed,color:'#20d7f0',r:73},
 {kind:'noPost',label:'فاقد پست معتبر',value:m.breakdownNoPost||0,color:'#ff6d78',r:55},
 {kind:'outside',label:'خارج از چارت',value:m.breakdownOutside,color:'#19b9a9',r:37}
 ];let angle=0,outer='';employment.forEach(s=>{if(!s.value)return;const size=s.value/total*360,start=angle,end=angle+size,mid=start+size/2,p=org115Polar(190,190,148,mid),pct=org115Pct(s.value,total);outer+=`<path class="org116-click-arc" d="${org116Arc(190,190,132,start+.7,end-.7)}" stroke="${s.color}" stroke-width="54" fill="none" data-status-detail="${s.kind}" data-status-scope-key="${esc(state.statusScope)}"><title>${esc(s.label)}: ${fa(s.value)} نفر، ${fa(pct)}٪</title></path>${pct>=4?`<text x="${p.x}" y="${p.y}" class="org116-arc-label">${fa(pct)}٪</text>`:''}`;angle=end});let rings='';special.forEach(s=>{const pct=org115Pct(s.value,total),circ=2*Math.PI*s.r,dash=circ*pct/100,g=org116GenderForKind(s.kind);rings+=`<circle cx="190" cy="190" r="${s.r}" class="org116-ring-bg"></circle><circle cx="190" cy="190" r="${s.r}" class="org116-click-ring" stroke="${s.color}" stroke-dasharray="${dash} ${circ-dash}" data-status-detail="${s.kind}" data-status-scope-key="${esc(state.statusScope)}"><title>${esc(s.label)}: ${fa(s.value)} نفر (${fa(pct)}٪)؛ مرد ${fa(g.male)}، زن ${fa(g.female)}</title></circle>`});const legend=[...employment,...special].map(s=>{const g=org116GenderForKind(s.kind),pct=org115Pct(s.value,total);return `<button type="button" style="--c:${s.color}" data-status-detail="${s.kind}" data-status-scope-key="${esc(state.statusScope)}" data-count="${s.value}" data-male="${g.male}" data-female="${g.female}" data-unknown="${g.unknown}"><i></i><span><b>${esc(s.label)}</b><small>${fa(s.value)} نفر • ${fa(pct)}٪ • مرد ${fa(g.male)} • زن ${fa(g.female)}</small></span></button>`}).join('');host.innerHTML=`<div class="org116-chart-grid"><div class="org116-radial"><svg viewBox="0 0 380 380" role="img" aria-label="ترکیب نیروی انسانی">${outer}${rings}<circle cx="190" cy="190" r="24" class="org116-center-disc"></circle><text x="190" y="181" class="org116-center-total">${fa(m.operational)}</text><text x="190" y="207" class="org116-center-caption">نیروی یکتا</text></svg></div><div class="org116-chart-legend">${legend}</div></div><p class="org116-overlap-note"><b>راهنما:</b> حلقه بیرونی گروه‌های استخدامی و جمع آن دقیقاً ۱۰۰٪ است. حلقه‌های داخلی ویژگی‌های هم‌پوشان‌اند و درصد هرکدام مستقل از کل نیروی همان حوزه محاسبه شده است.</p>`;org112BindDetailTriggers(host)}
function org115RenderEmployment(m){const total=Math.max(1,m.operational);$('#statusEmploymentKpis').innerHTML=[
 org116EmploymentCard('formal','رسمی',m.breakdownFormal,total,org115Colors.green,'R'),
 org116EmploymentCard('company','شرکتی',m.breakdownCompany,total,org115Colors.white,'S'),
 org116EmploymentCard('volume','حجمی',m.breakdownVolume,total,org115Colors.purple,'V'),
 
 org116EmploymentCard('consultant','مشاور',m.breakdownConsultant,total,org115Colors.rose,'M')].join('');
 $('#statusSpecialKpis').innerHTML=[
 org116SpecialCard('hold','حفظ پست',m.breakdownHold,total,org115Colors.orange,'H','پست مصوب مبدأ متفاوت از استقرار فعلی'),
 org116SpecialCard('named','پست با نام',m.breakdownNamed,total,'#174a70','N','ویژگی مستقل پست با نام'),
 org116SpecialCard('noPost','فاقد پست معتبر',m.breakdownNoPost||0,total,'#ff6d78','X','فاقد پست مصوب معتبر'),
 org116SpecialCard('outside','خارج از چارت',m.breakdownOutside,total,'#19b9a9','O','استقرار خارج از ساختار مصوب')].join('');
 org116RenderWorkforceChart(m)}

org112DetailPersonRows=function(people,kind){return people.map(p=>{const hold=org112IsHoldPerson(p),hm=hold?org112HoldMeta(p):null,g=org82GenderOf(p),gender=g==='female'?'زن':g==='male'?'مرد':'نامشخص';return`<tr data-status-person="${esc(p.id)}" data-gender="${g}"><td><b>${esc(p.full_name)}</b><small>شماره ${esc(p.personnel_no||'—')}</small></td><td><span class="org116-gender-pill ${g}">${gender}</span></td><td><span class="org112-group-pill">${esc(p.employment_group||'—')}</span></td><td>${esc(p.position_title||'—')}<small>${p.position_code?`کد ${esc(p.position_code)}`:''}</small></td><td>${esc(p.organizational_unit||'—')}</td><td>${esc(p.actual_location||'—')}<small>${esc(p.activity_area||'')}</small></td>${kind==='hold'?`<td><b>${esc(hm.currentUnit||'—')}</b><small>${esc(hm.currentPost||'')}</small></td>`:''}<td>${[hold?'حفظ پست':'',p.named_post?'پست با نام':'',p.outside_chart?'خارج چارت':'',org116NoValidPost(p)?'فاقد پست معتبر':''].filter(Boolean).map(x=>`<span class="org112-hold-pill">${x}</span>`).join(' ')||'—'}</td></tr>`}).join('')}
org112ExportDetail=function(kind,key,items){const def=ORG112_DETAIL_KINDS[kind],scope=scopeLabel(key);if(def.posts){const rows=items.map((r,i)=>[i+1,r.postTitle,r.nodeId,r.scopeLabel,r.page,'خالی واقعی',r.auditConclusion||'']);downloadProfessionalXlsx({title:def.label,subtitle:`حوزه: ${scope} — ${fa(items.length)} پست`,sheetName:'پست‌های خالی',columns:[['ردیف',8],['عنوان پست مصوب',38],['شناسه پست',20],['واحد/صفحه',34],['صفحه',10],['وضعیت',16],['نتیجه ممیزی',55]],rows,summary:[['حوزه',scope],['تعداد پست خالی واقعی',items.length]],filename:`جزئیات-${def.label}-${scope}.xlsx`});return}const g=org116GenderStats(items),rows=items.map((p,i)=>{const h=org112IsHoldPerson(p)?org112HoldMeta(p):null,gender=org82GenderOf(p)==='female'?'زن':org82GenderOf(p)==='male'?'مرد':'نامشخص';return[i+1,p.full_name,p.personnel_no,gender,p.employment_group,p.position_title,p.position_code,p.organizational_unit,p.actual_location,p.activity_area,h?'بله':'خیر',p.named_post?'بله':'خیر',org116NoValidPost(p)?'بله':'خیر',p.outside_chart?'بله':'خیر',h?.currentUnit||'',h?.currentPost||'']});downloadProfessionalXlsx({title:def.label,subtitle:`حوزه: ${scope} — ${fa(items.length)} نفر یکتا`,sheetName:'فهرست افراد',columns:[['ردیف',8],['نام و نام خانوادگی',30],['شماره پرسنلی',16],['جنسیت',12],['نوع همکاری',16],['عنوان پست',32],['کد پست',14],['واحد سازمانی مصوب',34],['محل خدمت واقعی',28],['حوزه فعالیت',28],['حفظ پست',14],['پست با نام',14],['فاقد پست معتبر',18],['خارج چارت',14],['حوزه فعلی در چارت',34],['جایگاه فعلی',34]],rows,summary:[['حوزه',scope],['نوع فهرست',def.label],['تعداد افراد یکتا',items.length],['مرد',g.male],['زن',g.female],['جنسیت نامشخص',g.unknown]],filename:`جزئیات-${def.label}-${scope}.xlsx`})}
showStatusMetricDetails=function(kind,key=state.statusScope){const def=ORG112_DETAIL_KINDS[kind];if(!def)return;const scope=scopeLabel(key),isPosts=!!def.posts,items=isPosts?org112VacantPostsForScope(key):org112PeopleForDetail(kind,key),count=items.length,g=isPosts?null:org116GenderStats(items);const extra=kind==='hold'?'<p class="org112-detail-explain">فرد حفظ پست در گروه استخدامی اصلی خود نیز باقی می‌ماند؛ این ویژگی هم‌پوشان است.</p>':kind==='noPost'?'<p class="org112-detail-explain">این فهرست شامل افرادی است که پست مصوب معتبر برای آنان ثبت نشده است؛ نوع همکاری اصلی آنان مستقل باقی می‌ماند.</p>':isPosts?'<p class="org112-detail-explain">این فهرست فقط پست‌های مصوب بدون متصدی معتبر را نشان می‌دهد.</p>':'';const head=isPosts?'<tr><th>ردیف</th><th>عنوان پست مصوب</th><th>واحد</th><th>صفحه</th><th>وضعیت</th><th>مبنای ممیزی</th></tr>':`<tr><th>نام</th><th>جنسیت</th><th>نوع همکاری</th><th>عنوان و کد پست</th><th>واحد مصوب</th><th>محل و حوزه فعلی</th>${kind==='hold'?'<th>استقرار فعلی چارت</th>':''}<th>وضعیت ویژه</th></tr>`;const body=isPosts?org112DetailVacancyRows(items):org112DetailPersonRows(items,kind),genderSummary=isPosts?'':`<div class="org116-modal-gender">${org116GenderBadges(g)}<div class="org116-gender-filters"><button type="button" data-gender-filter="all" class="active">همه ${fa(count)}</button><button type="button" data-gender-filter="male">مرد ${fa(g.male)}</button><button type="button" data-gender-filter="female">زن ${fa(g.female)}</button>${g.unknown?`<button type="button" data-gender-filter="unknown">نامشخص ${fa(g.unknown)}</button>`:''}</div></div>`;$('#personModalContent').innerHTML=`<div class="org112-detail-head"><div><span>وضعیت چارت • ${esc(scope)}</span><h2>${esc(def.label)}</h2><p><b>${fa(count)}</b> ${isPosts?'پست':'نفر یکتا'}؛ عدد کارت، نمودار، فهرست و Excel یکسان است.</p></div><div class="org112-detail-actions"><button id="org112DetailExport" class="secondary" type="button">خروجی Excel همین فهرست</button></div></div>${extra}${genderSummary}<div class="org112-detail-tools"><label>جست‌وجو در همین فهرست<input id="org112DetailSearch" placeholder="نام، شماره پرسنلی، پست، واحد یا حوزه"></label><span id="org112DetailVisible">${fa(count)} مورد</span></div><div class="org112-detail-table"><table><thead>${head}</thead><tbody>${body||`<tr><td colspan="9"><div class="empty-state"><p>موردی در این وضعیت ثبت نشده است.</p></div></td></tr>`}</tbody></table></div>`;const modal=$('#personModal');modal.classList.remove('hidden');modal.classList.add('org112-status-detail-modal');$('#org112DetailExport').onclick=()=>org112ExportDetail(kind,key,items);const search=$('#org112DetailSearch'),tbody=$('.org112-detail-table tbody');let genderFilter='all';const apply=()=>{const q=norm(search?.value||'');let visible=0;tbody?.querySelectorAll('tr').forEach(tr=>{const genderOk=isPosts||genderFilter==='all'||tr.dataset.gender===genderFilter,searchOk=!q||norm(tr.textContent).includes(q),show=genderOk&&searchOk;tr.hidden=!show;if(show)visible++});$('#org112DetailVisible').textContent=`${fa(visible)} مورد`};if(search)search.oninput=apply;document.querySelectorAll('[data-gender-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-gender-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');genderFilter=b.dataset.genderFilter;apply()});tbody?.querySelectorAll('[data-status-person]').forEach(tr=>tr.onclick=()=>{modal.classList.remove('org112-status-detail-modal');openPerson(tr.dataset.statusPerson)});modal.dataset.statusDetailKind=kind;modal.dataset.statusDetailScope=key}

function org116TableSummary(rows,m){const average=rows.length?Math.round(rows.reduce((a,x)=>a+x.metrics.currentPercent,0)/rows.length):m.currentPercent,totalVac=rows.reduce((a,x)=>a+x.metrics.emptyPosts,0),totalHold=rows.reduce((a,x)=>a+x.metrics.breakdownHold,0),totalPeople=rows.reduce((a,x)=>a+x.metrics.operational,0),female=rows.reduce((a,x)=>a+x.metrics.female,0),male=rows.reduce((a,x)=>a+x.metrics.male,0);$('#statusTableSummary').innerHTML=[['تعداد واحدها',rows.length,org115Colors.purple],['میانگین اشغال',average+'٪',org115Colors.green],['کل نیروی فعلی',totalPeople,org115Colors.blue],['مرد',male,'#4f9cff'],['زن',female,'#f56ab4'],['کل پست خالی',totalVac,org115Colors.red],['کل حفظ پست',totalHold,org115Colors.orange]].map(x=>`<article class="org115-table-stat" style="--c:${x[2]}"><span>${x[0]}</span><strong>${typeof x[1]==='string'?esc(x[1]):fa(x[1])}</strong></article>`).join('')}
org115RenderTableSummary=org116TableSummary;
org115RenderUnitRanking=function(rows){const host=$('#statusUnitRanking');const section=host?.closest('.org117-ranking-section')||document.querySelector('#page-statusChart .org117-ranking-section');if(section)section.remove();if(host)host.innerHTML='';}
function org116Tone(p){return p>=90?'good':p>=75?'warn':'bad'}
function org116RenderTableInsights(rows){const heat=$('#statusUnitHeatmap'),att=$('#statusAttentionUnits'),comp=$('#statusUnitComposition');if(!heat||!att||!comp)return;const show=rows.slice().sort((a,b)=>b.metrics.operational-a.metrics.operational).slice(0,8);heat.innerHTML=`<div class="org116-heat-head"><span>واحد</span><span>اشغال</span><span>پست خالی</span><span>تراکم نفر</span></div>${show.map(x=>`<button type="button" data-status-scope="${esc(x.key)}"><b>${esc(x.label)}</b><i class="${org116Tone(x.metrics.currentPercent)}">${fa(x.metrics.currentPercent)}٪</i><i class="${x.metrics.emptyPosts?'bad':'good'}">${fa(x.metrics.emptyPosts)}</i><i class="${x.metrics.personnelLoadPercent>115?'warn':'good'}">${fa(x.metrics.personnelLoadPercent)}٪</i></button>`).join('')}`;const attention=rows.slice().sort((a,b)=>(b.metrics.emptyPosts*4+(100-b.metrics.currentPercent)+b.metrics.breakdownHold)-(a.metrics.emptyPosts*4+(100-a.metrics.currentPercent)+a.metrics.breakdownHold)).slice(0,5);att.innerHTML=attention.map((x,i)=>`<button type="button" data-status-scope="${esc(x.key)}"><span>${fa(i+1)}</span><div><b>${esc(x.label)}</b><small>${fa(x.metrics.emptyPosts)} پست خالی • ${fa(x.metrics.breakdownHold)} حفظ پست • اشغال ${fa(x.metrics.currentPercent)}٪</small></div><i>←</i></button>`).join('');comp.innerHTML=show.slice(0,5).map(x=>{const m=x.metrics,total=Math.max(1,m.operational),segs=[[m.breakdownFormal,org115Colors.green],[m.breakdownCompany,org115Colors.white],[m.breakdownVolume,'#5ad9e8'],[m.breakdownContract,'#6d83ff'],[m.breakdownConsultant,org115Colors.purple]];return`<button type="button" data-status-scope="${esc(x.key)}"><div><b>${esc(x.label)}</b><small>مرد ${fa(m.male)} • زن ${fa(m.female)}</small></div><span class="org116-stack">${segs.map(s=>`<i style="width:${org115Pct(s[0],total)}%;background:${s[1]}"></i>`).join('')}</span></button>`}).join('');document.querySelectorAll('#statusUnitHeatmap [data-status-scope],#statusAttentionUnits [data-status-scope],#statusUnitComposition [data-status-scope]').forEach(b=>b.onclick=()=>openStatusScope(b.dataset.statusScope))}
org115RenderTableRows=function(){const all=org115FilteredRows(),pages=Math.max(1,Math.ceil(all.length/org115TableState.pageSize));org115TableState.page=Math.min(org115TableState.page,pages);const start=(org115TableState.page-1)*org115TableState.pageSize,rows=all.slice(start,start+org115TableState.pageSize),host=$('#statusTable');const cell=(kind,val,key,cls='')=>`<td class="${cls}"><button type="button" class="org112-table-number" data-status-detail="${kind}" data-status-scope-key="${esc(key)}">${org116Num(val)}</button></td>`;host.innerHTML=`<table><thead><tr><th>واحد</th><th>پست مصوب</th><th>پست پر</th><th>پست خالی</th><th>اشغال</th><th>نیروی فعلی</th><th>مرد</th><th>زن</th><th>حفظ پست</th><th>پست با نام</th><th>فاقد پست</th><th>وضعیت</th></tr></thead><tbody>${rows.map(x=>{const m=x.metrics,[status,color]=org115TableRowStatus(m),occCls=m.currentPercent<70?'bad':m.currentPercent<85?'warn':'';return`<tr data-status-scope="${esc(x.key)}"><td><b>${esc(x.label)}</b></td><td>${org116Num(m.approved)}</td><td><button type="button" class="org112-table-number" data-org115-post-kind="occupied" data-org115-scope="${esc(x.key)}">${org116Num(m.occupiedPosts)}</button></td>${cell('empty',m.emptyPosts,x.key,'org112-empty-cell')}<td><span class="org115-occupancy-pill ${occCls}">${org116Num(m.currentPercent)}٪</span></td>${cell('all',m.operational,x.key)}<td><span class="org116-sex-number male">${org116Num(m.male)}</span></td><td><span class="org116-sex-number female">${org116Num(m.female)}</span></td>${cell('hold',m.breakdownHold,x.key,'org112-hold-cell')}${cell('named',m.breakdownNamed,x.key)}${cell('noPost',m.breakdownNoPost||0,x.key,'org116-nopost-cell')}<td><span class="status-result" style="border-color:${color};color:${color}">${status}</span></td></tr>`}).join('')||'<tr><td colspan="12">واحدی مطابق فیلتر فعلی پیدا نشد.</td></tr>'}</tbody></table>`;host.querySelectorAll('tr[data-status-scope]').forEach(r=>r.onclick=()=>openStatusScope(r.dataset.statusScope));org112BindDetailTriggers(host);org115BindPostDetails(host);$('#org115TablePager').innerHTML=`<span>نمایش ${org116Num(all.length?start+1:0)} تا ${org116Num(Math.min(start+org115TableState.pageSize,all.length))} از ${org116Num(all.length)} واحد</span><div><button id="org115Prev" type="button" ${org115TableState.page<=1?'disabled':''}>قبلی</button> <b>${org116Num(org115TableState.page)} / ${org116Num(pages)}</b> <button id="org115Next" type="button" ${org115TableState.page>=pages?'disabled':''}>بعدی</button></div>`;const prev=$('#org115Prev'),next=$('#org115Next');if(prev)prev.onclick=()=>{org115TableState.page--;org115RenderTableRows()};if(next)next.onclick=()=>{org115TableState.page++;org115RenderTableRows()}}
renderStatusTable=function(children){const rows=children.length?children:[{key:state.statusScope,label:scopeLabel(state.statusScope),metrics:statusMetrics()}];org115TableState.rows=rows;org115TableState.page=1;org115RenderTableSummary(rows,statusMetrics());org115RenderUnitRanking(rows);org115RenderTableRows();const search=$('#org115TableSearch'),sort=$('#org115TableSort');if(search){search.value='';search.oninput=()=>{org115TableState.query=search.value;org115TableState.page=1;org115RenderTableRows()}}if(sort){sort.value=org115TableState.sort;sort.onchange=()=>{org115TableState.sort=sort.value;org115TableState.page=1;org115RenderTableRows()}}document.querySelectorAll('[data-org115-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-org115-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');org115TableState.filter=b.dataset.org115Filter;org115TableState.page=1;org115RenderTableRows()})}

/* v4.1.42 — grouped seven-series subunit comparison chart.
   Employment groups are person counts; hold/named are overlapping special statuses;
   vacant posts are audited approved posts without a valid current occupant. */
const ORG118_STATUS_UI='subunit-grouped-six-series-v4.1.44';
const ORG142_COMPARE_PAGE_SIZE=6;
const org142ComparisonState={scope:'',page:0};
const ORG142_COMPARE_SERIES=Object.freeze([
  {kind:'formal',label:'رسمی',field:'breakdownFormal',color:'#3fa86b'},
  {kind:'company',label:'شرکتی',field:'breakdownCompany',color:'#3f7fc5'},
  {kind:'volume',label:'حجمی',field:'breakdownVolume',color:'#8b65d8'},
  
  {kind:'hold',label:'حفظ پست',field:'breakdownHold',color:'#b38a32'},
  {kind:'named',label:'پست با نام',field:'breakdownNamed',color:'#2f7d8c'},
  {kind:'empty',label:'پست خالی',field:'emptyPosts',color:'#df5b67'}
]);
function org142NiceMaximum(value){
  const v=Math.max(1,Number(value)||1);
  if(v<=10)return Math.ceil(v/2)*2;
  if(v<=50)return Math.ceil(v/10)*10;
  if(v<=100)return Math.ceil(v/20)*20;
  if(v<=300)return Math.ceil(v/50)*50;
  if(v<=800)return Math.ceil(v/100)*100;
  return Math.ceil(v/200)*200;
}
function org142MetricSeries(metrics){
  return ORG142_COMPARE_SERIES.map(x=>({...x,value:Math.max(0,Number(metrics?.[x.field]||0))}));
}
function org142UnitIcon(index){return ['◫','◎','◇','⌁','▥','◉'][index%6]}
function org142RenderComparison(data){
  const host=$('#statusCompareChart'),legend=$('#statusSeriesLegend'),subtitle=$('#statusCompareSubtitle');
  if(!host)return;
  const scope=String(state.statusScope||'company');
  if(org142ComparisonState.scope!==scope){org142ComparisonState.scope=scope;org142ComparisonState.page=0}
  const pageCount=Math.max(1,Math.ceil(data.length/ORG142_COMPARE_PAGE_SIZE));
  org142ComparisonState.page=Math.max(0,Math.min(org142ComparisonState.page,pageCount-1));
  const from=org142ComparisonState.page*ORG142_COMPARE_PAGE_SIZE;
  const pageData=data.slice(from,from+ORG142_COMPARE_PAGE_SIZE);
  const allValues=pageData.flatMap(x=>org142MetricSeries(x.metrics||statusMetrics(x.key)).map(y=>y.value));
  const maximum=org142NiceMaximum(Math.max(1,...allValues));
  const ticks=[maximum,Math.round(maximum*.75),Math.round(maximum*.5),Math.round(maximum*.25),0];
  if(legend)legend.innerHTML=ORG142_COMPARE_SERIES.map(x=>`<span class="org142-legend-item" style="--series:${x.color}"><i></i>${esc(x.label)}</span>`).join('');
  if(subtitle)subtitle.textContent=`نمایش ${fa(from+1)} تا ${fa(Math.min(from+pageData.length,data.length))} از ${fa(data.length)} حوزه؛ سه ستون اول گروه استخدامی‌اند و «حفظ پست» و «پست با نام» وضعیت‌های هم‌پوشان هستند.`;
  const units=pageData.map((x,index)=>{
    const a=x.metrics||statusMetrics(x.key),series=org142MetricSeries(a);
    const bars=series.map(item=>{
      const height=Math.max(item.value?3:1,Math.min(100,item.value/maximum*100));
      const zero=item.value===0?' is-zero':'';
      return `<div class="org142-bar-slot" data-org142-kind="${item.kind}"><button type="button" class="org142-bar${zero}" style="--bar-height:${height}%;--bar-color:${item.color}" data-status-detail="${item.kind}" data-status-scope-key="${esc(x.key)}" aria-label="${esc(x.label)}؛ ${esc(item.label)} ${fa(item.value)}"><span class="org142-bar-value">${fa(item.value)}</span><span class="org142-bar-tip"><b>${esc(item.label)}</b><em>${fa(item.value)} ${item.kind==='empty'?'پست':'نفر'}</em><small>${esc(x.label)}</small></span></button></div>`;
    }).join('');
    return `<article class="org142-unit-column">
      <div class="org142-bars" aria-label="نمودار ${esc(x.label)}">${bars}</div>
      <button type="button" class="org142-unit-name" data-status-scope="${esc(x.key)}" title="ورود به ${esc(x.label)}"><span>${org142UnitIcon(from+index)}</span><b>${esc(x.label)}</b></button>
      <button type="button" class="org142-unit-summary" data-status-scope="${esc(x.key)}">
        <strong>${org116Num(a.currentPercent)}٪<small>درصد اشغال</small></strong>
        <span>ظرفیت <b>${org116Num(a.approved)}</b></span>
        <span>نیروی فعلی <b>${org116Num(a.operational)}</b></span>
        <span>پست خالی <b>${org116Num(a.emptyPosts)}</b></span>
      </button>
    </article>`;
  }).join('');
  const minWidth=Math.max(900,pageData.length*176);
  host.innerHTML=`<div class="org142-chart-shell">
    <div class="org142-chart-toolbar"><div><b>نمودار میله‌ای مقایسه‌ای</b><small>برای مشاهده فهرست دقیق، روی هر ستون کلیک کنید.</small></div><div class="org142-pager"${pageCount<=1?' hidden':''}><button type="button" id="org142Prev" ${org142ComparisonState.page<=0?'disabled':''}>قبلی</button><span>صفحه ${fa(org142ComparisonState.page+1)} از ${fa(pageCount)}</span><button type="button" id="org142Next" ${org142ComparisonState.page>=pageCount-1?'disabled':''}>بعدی</button></div></div>
    <div class="org142-chart-scroll"><div class="org142-chart-layout" style="--chart-min:${minWidth}px">
      <div class="org142-y-axis">${ticks.map(v=>`<span>${fa(v)}</span>`).join('')}</div>
      <div class="org142-plot-shell">
        <div class="org142-plot-area"><div class="org142-grid-lines">${ticks.map(()=>'<i></i>').join('')}</div><div class="org142-units" style="--unit-count:${Math.max(1,pageData.length)}">${units}</div></div>
      </div>
    </div></div>
    <p class="org142-chart-note"><b>راهنمای محاسبه:</b> رسمی، شرکتی و حجمی تعداد افراد هستند؛ حفظ پست و پست با نام ممکن است با گروه استخدامی همان فرد هم‌پوشانی داشته باشند؛ پست خالی فقط ظرفیت مصوب بدون متصدی معتبر است.</p>
  </div>`;
  host.querySelectorAll('[data-status-scope]').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();openStatusScope(b.dataset.statusScope)});
  org112BindDetailTriggers(host);
  const prev=$('#org142Prev'),next=$('#org142Next');
  if(prev)prev.onclick=()=>{if(org142ComparisonState.page>0){org142ComparisonState.page--;org142RenderComparison(data)}};
  if(next)next.onclick=()=>{if(org142ComparisonState.page<pageCount-1){org142ComparisonState.page++;org142RenderComparison(data)}};
}
