  const approvedPost=org76FaText(approvedNode?.text||p?.position_title||base.approvedPost||'ثبت نشده');
  const currentUnit=org76FaText(p?.actual_location||getSlide(base.currentPage)?.title||base.currentUnit||'ثبت نشده');
  const currentPost=org76FaText(p?.activity_area||currentNode?.text||p?.actual_location||base.currentPost||'ثبت نشده');
  const semanticMismatch=org119SemanticHold(p);
  const generated=`پست و واحد مصوب در «${approvedUnit}» ثبت است، اما حوزه فعالیت فعلی «${currentPost||currentUnit}» و محل خدمت فعلی «${currentUnit}» است.`;
  const reason=semanticMismatch?generated:(p?.hold_mapping_reason||base.reason||p?.placement_evidence||p?.mapping_reason||generated);
  return {...base,approvedUnit,approvedPost,currentUnit,currentPost,reason:org76FaText(reason)};
