state.currentUser=null;state.permissions={manage_users:false};state.isOwner=false;
function org159Date(value){if(!value)return 'ثبت نشده';try{return new Date(value).toLocaleString('fa-IR')}catch(e){return String(value)}}
function org159RoleLabel(role){return ORG421_ACCESS.roleLabel(role)}
function org159SetIdentity(user){state.currentUser=user||null;state.isOwner=user?.role==='owner';state.permissions=ORG421_ACCESS.normalize(user?.role||'admin',user?.permissions||{});const cp=$('#changePassword');if(cp){cp.disabled=false;cp.classList.remove('hidden');cp.title='تغییر رمز با تأیید رمز فعلی'}}
showLogin=function(){
 const panel=document.querySelector('.v4132-login-panel');if(panel)panel.scrollTop=0;
 $('#loginScreen').classList.remove('hidden');$('#loginChoice').classList.remove('hidden');$('#passwordForm').classList.add('hidden');
 $('#loginTitle').textContent='خوش آمدید';$('#loginDesc').textContent='برای ادامه، نوع دسترسی خود را انتخاب کنید.';$('#loginError').textContent='';
 const u=$('#usernameInput'),p=$('#passwordInput');if(u){u.value='';u.disabled=false}if(p){p.value='';p.disabled=false}$('#passwordSubmit').disabled=false;
};
showPasswordForm=function(){
 const panel=document.querySelector('.v4132-login-panel');if(panel)panel.scrollTop=0;
 $('#loginChoice').classList.add('hidden');$('#passwordForm').classList.remove('hidden');$('#loginTitle').textContent='ورود مدیریتی';
 $('#loginDesc').textContent='نام کاربری و رمز شخصی خود را وارد کنید.';$('#passwordSubmit').textContent='ورود به داشبورد مدیریتی';
 $('#usernameInput').value='';$('#passwordInput').value='';$('#loginError').textContent='';setTimeout(()=>$('#usernameInput')?.focus(),30);
};
showServerRequiredMessage=function(){
 $('#loginDesc').textContent='برای ورود مدیریتی، نسخه امن محلی باید در حال اجرا باشد.';
 $('#loginError').textContent='فایل «SazmanHR.exe» را باز کنید و سپس دوباره وارد شوید.';
};
chooseRole=async function(role){
 state.role=role;$('#loginError').textContent='';if(state.runtimeReady)await state.runtimeReady;
 if(role==='viewer'){
  setLoginBusy(true,'در حال آماده‌سازی حالت مشاهده…');
  try{
   if(state.server){const j=await api.post('/login',{mode:'viewer'});state.token=j.token;state.role='viewer';org159SetIdentity(j.user);state.data=await api.get('/bootstrap');hydrate(state.data)}
   else{state.token='';state.role='viewer';org159SetIdentity({username:'viewer',full_name:'مشاهده‌گر',title:'فقط مشاهده و گزارش',role:'viewer'});await ensureStandaloneData()}
   await enterApp();
  }catch(err){$('#loginError').textContent=String(err.message||err)}finally{setLoginBusy(false)}
  return;
 }
 if(!state.server){showPasswordForm();showServerRequiredMessage();return}
 showPasswordForm();
};
completeRequiredPasswordChange=async function(){
 const first=window.prompt('رمز موقت را تغییر دهید. رمز جدید حداقل ۱۰ نویسه و ترکیبی باشد:');if(!first)throw new Error('تغییر رمز اولیه لغو شد.');
 const second=window.prompt('رمز جدید را دوباره وارد کنید:');const normalizedFirst=latinDigits(first).trim(),normalizedSecond=latinDigits(second).trim();if(normalizedFirst!==normalizedSecond)throw new Error('تکرار رمز با رمز جدید یکسان نیست.');
 await api.post('/change-password',{password:normalizedFirst});if(state.currentUser)state.currentUser.must_change=false;toast('رمز شخصی شما ثبت شد','فایل رمز موقت دیگر معتبر نیست.');
};
loginSubmit=async function(e){
 e.preventDefault();if(!state.server){showServerRequiredMessage();return}
 const username=latinDigits($('#usernameInput')?.value||'').trim().toLowerCase(),pass=latinDigits($('#passwordInput').value).trim();$('#loginError').textContent='';
 if(!username){$('#loginError').textContent='نام کاربری را وارد کنید.';return}if(!pass){$('#loginError').textContent='رمز عبور را وارد کنید.';return}
 setLoginBusy(true,'در حال بررسی حساب کاربری…');
 try{const j=await api.post('/login',{username,password:pass});state.token=j.token;state.role='admin';org159SetIdentity(j.user);state.permissions=j.permissions||state.permissions;if(j.must_change)await completeRequiredPasswordChange();state.data=await api.get('/bootstrap');hydrate(state.data);await enterApp()}
 catch(err){$('#loginError').textContent=String(err.message||err).replace(/^Error:\s*/,'')}
 finally{setLoginBusy(false)}
};
enterApp=async function(){
 $('#loginScreen').classList.add('hidden');$('#appShell').classList.remove('hidden');const admin=state.role==='admin';
 org421ApplyPermissionUi();
 const user=state.currentUser||{full_name:admin?'کاربر مدیریتی':'مشاهده‌گر',title:admin?'دسترسی مدیریتی':'فقط مشاهده و گزارش'};
 $('#roleName').textContent=user.full_name;$('#userMode').textContent=user.title||org159RoleLabel(user.role);$('#avatar').textContent=(user.full_name||'ک').trim().slice(0,1);
 state.pageHistory=[];state.statusScopeHistory=[];renderAll();perfMark('sazmanhr-app-shell-ready');navigate('formalChart',{replace:true});
};
logout=function(){const token=state.token;if(state.server&&token)api.post('/logout',{}).catch(()=>{});state.token='';state.data=state.server?null:state.data;state.people=state.server?[]:state.people;state.pageHistory=[];org159SetIdentity(null);$('#appShell').classList.add('hidden');showLogin()};

function org159TemporaryPasswordCard(user,password){
 $('#personModalContent').innerHTML=`<div class="user-secret-card"><span>رمز موقت یک‌بارمصرف</span><h2>${esc(user?.full_name||user?.username||'کاربر')}</h2><p>این رمز فقط همین یک‌بار نمایش داده می‌شود. آن را امن به کاربر تحویل دهید؛ در اولین ورود باید تغییر کند.</p><code id="org159TempPassword">${esc(password)}</code><div class="profile-actions"><button class="secondary" id="org159CopyPassword" type="button">کپی رمز</button><button class="primary" id="org159CloseSecret" type="button">متوجه شدم</button></div></div>`;
 $('#personModal').classList.remove('hidden');$('#org159CopyPassword').onclick=async()=>{try{await navigator.clipboard.writeText(password);toast('رمز کپی شد')}catch(e){toast('امکان کپی خودکار نبود','رمز را دستی یادداشت کنید.','error')}};$('#org159CloseSecret').onclick=()=>$('#personModal').classList.add('hidden');
}
function org159UserDetails(user){
 const summary=ORG421_ACCESS.permissionSummary(user.role,user.permissions);const tags=user.role==='owner'?'<span>دسترسی کامل مدیر اصلی</span>':ORG421_ACCESS.formValues(user.role,user.permissions).filter(x=>x.checked).map(x=>`<span>${esc(x.label)}</span>`).join('')||'<span>دسترسی پایه مدیریتی</span>';
 $('#personModalContent').innerHTML=`<div class="profile-modal-head"><div class="avatar">${esc((user.full_name||'?').slice(0,1))}</div><div><h2>${esc(user.full_name)}</h2><p>${esc(user.title||org159RoleLabel(user.role))}</p></div></div><div class="user-detail-grid"><div><span>نام کاربری</span><b>${esc(user.username)}</b></div><div><span>سطح دسترسی</span><b>${esc(org159RoleLabel(user.role))}</b></div><div><span>شماره همراه</span><b dir="ltr">${esc(user.phone||'ثبت نشده')}</b></div><div><span>وضعیت</span><b>${user.active?'فعال':'غیرفعال'}</b></div><div><span>آخرین ورود</span><b>${esc(org159Date(user.last_login_at))}</b></div><div><span>تاریخ ایجاد حساب</span><b>${esc(org159Date(user.created_at))}</b></div></div><div class="permission-summary" title="${esc(summary)}">${tags}</div>`;$('#personModal').classList.remove('hidden');
}
function org159UserForm(user=null){
 const editing=!!user;$('#personModalContent').innerHTML=`<form id="org159UserForm" class="user-form"><div class="modal-title"><h2>${editing?'ویرایش حساب کاربری':'افزودن کاربر مدیریتی'}</h2><p>${editing?'اطلاعات تماس و عنوان کاربر را اصلاح کنید.':'برای کاربر یک رمز موقت تصادفی ساخته می‌شود.'}</p></div><div class="form-grid"><label><span>نام و نام خانوادگی</span><input name="full_name" required value="${esc(user?.full_name||'')}"/></label><label><span>نام کاربری انگلیسی</span><input name="username" required dir="ltr" ${editing?'readonly':''} value="${esc(user?.username||'')}" placeholder="مثلاً ali.ahmadi"/></label><label><span>عنوان / سمت در سامانه</span><input name="title" required value="${esc(user?.title||'کاربر مدیریتی')}"/></label><label><span>شماره همراه</span><input name="phone" dir="ltr" inputmode="tel" value="${esc(user?.phone||'')}"/></label></div><div class="profile-actions"><button class="secondary" type="button" id="org159CancelUser">انصراف</button><button class="primary" type="submit">${editing?'ذخیره تغییرات':'ایجاد حساب'}</button></div></form>`;$('#personModal').classList.remove('hidden');$('#org159CancelUser').onclick=()=>$('#personModal').classList.add('hidden');
 $('#org159UserForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget).entries());try{const result=await api.post(editing?'/users/update':'/users/create',data);$('#personModal').classList.add('hidden');await renderUserManagement();if(result.temporary_password)org159TemporaryPasswordCard(result.user,result.temporary_password);else toast('حساب کاربری ذخیره شد',result.user.full_name)}catch(err){toast('ثبت حساب انجام نشد',err.message,'error')}};
}
async function org159ToggleUser(user){if(user.role==='owner')return toast('مدیر اصلی همیشه فعال است','','error');const active=!user.active;if(!confirm(`حساب «${user.full_name}» ${active?'فعال':'غیرفعال'} شود؟`))return;try{await api.post('/users/toggle',{username:user.username,active});await renderUserManagement();toast('وضعیت حساب تغییر کرد',user.full_name)}catch(e){toast('تغییر وضعیت انجام نشد',e.message,'error')}}
