/* ========================================================================
   v4.1.64 — fully portable Windows runtime without Python.
   The native EXE serves static files and a compact local JSON API. Personnel
   changes use the same standalone UI but are persisted by the EXE beside the
   application, rather than depending on Python, SQLite APIs, or browser-only
   storage. Legacy direct index.html remains viewer-only.
   ======================================================================== */
const org162PreviousSetRuntimePanel=setRuntimePanel;
setRuntimePanel=function(status={}){
 if(status.portable){
  state.portable=true;const dot=$('#loginRuntimeDot'),title=$('#loginRuntimeTitle'),text=$('#loginRuntimeText'),open=$('#openLocalServer');
  if(dot)dot.className='runtime-dot online';
  if(IS_DESKTOP){
   if(title)title.textContent='برنامه دسکتاپ آفلاین آماده است';if(text)text.textContent='ورود مدیریتی و ذخیره اطلاعات در پنجره مستقل ویندوز فعال است.';
   if($('#serverStatus'))$('#serverStatus').textContent='برنامه دسکتاپ';if($('#serverSub'))$('#serverSub').textContent='محلی و بدون مرورگر خارجی';if($('#runtimeMode'))$('#runtimeMode').textContent='برنامه دسکتاپ آفلاین — پنجره مستقل';
  }else{
   if(title)title.textContent='نسخه مستقل کامل آماده است';if(text)text.textContent='ورود مدیریتی و ذخیره اطلاعات بدون نصب Python فعال است.';
   if($('#serverStatus'))$('#serverStatus').textContent='نسخه مستقل کامل';if($('#serverSub'))$('#serverSub').textContent='ذخیره محلی کنار برنامه';if($('#runtimeMode'))$('#runtimeMode').textContent='اجرای مستقل ویندوز — بدون Python';
  }
  if(open)open.classList.add('hidden');if($('#serverDot'))$('#serverDot').style.background='#36d17c';return;
 }
 org162PreviousSetRuntimePanel(status)
};
const org162PreviousLoadStandaloneData=loadStandaloneData;
loadStandaloneData=async function(){
 if(state.portable){const data=await portableApi.get('/bootstrap');if(!data?.people||!data?.slides)throw new Error('داده قابل استفاده از اجرای مستقل دریافت نشد.');data.app={...(data.app||{}),version:APP_VERSION};return data}
 return org162PreviousLoadStandaloneData()
};
const org162PreviousPersistStandalone=persistStandalone;
persistStandalone=async function(){
 state.data.people=state.people;state.data.summary=computeSummary();state.data.app={...(state.data.app||{}),version:APP_VERSION};state.summary=state.data.summary;
 if(state.portable){if(!state.token)return true;await portableApi.post('/data/save',state.data);return true}
 return org162PreviousPersistStandalone()
};
showServerRequiredMessage=function(){
 $('#loginDesc').textContent='ورود مدیریتی فقط از اجرای برنامه فعال می‌شود.';
 $('#loginError').textContent='فایل «SazmanHR.exe» را از پوشه استخراج‌شده اجرا کنید.';
 $('#passwordInput').disabled=true;$('#passwordSubmit').disabled=true;$('#openLocalServer').classList.add('hidden');
};
chooseRole=async function(role){
 state.role=role;$('#loginError').textContent='';if(state.runtimeReady)await state.runtimeReady;
 if(role==='viewer'){
  setLoginBusy(true,'در حال آماده‌سازی حالت مشاهده…');
  try{state.token='';state.role='viewer';org159SetIdentity({username:'viewer',full_name:'مشاهده‌گر',title:'فقط مشاهده و گزارش',role:'viewer'});await ensureStandaloneData();await enterApp()}
  catch(err){$('#loginError').textContent=String(err.message||err)}finally{setLoginBusy(false)}return;
 }
 showPasswordForm();
 if(state.portable||state.server){$('#loginDesc').textContent='نام کاربری و رمز شخصی خود را وارد کنید.';$('#usernameInput').disabled=false;$('#passwordInput').disabled=false;$('#passwordSubmit').disabled=false;$('#openLocalServer').classList.add('hidden');return}
 showServerRequiredMessage()
};
completeRequiredPasswordChange=async function(){
 const first=window.prompt('رمز موقت را تغییر دهید. رمز جدید حداقل ۱۰ نویسه و ترکیبی باشد:');if(!first)throw new Error('تغییر رمز اولیه لغو شد.');
 const second=window.prompt('رمز جدید را دوباره وارد کنید:');const normalizedFirst=latinDigits(first).trim(),normalizedSecond=latinDigits(second).trim();if(normalizedFirst!==normalizedSecond)throw new Error('تکرار رمز با رمز جدید یکسان نیست.');
 if(state.portable)await portableApi.post('/change-password',{password:normalizedFirst});else await api.post('/change-password',{password:normalizedFirst});
 if(state.currentUser)state.currentUser.must_change=false;toast('رمز شخصی شما ثبت شد','رمز موقت قبلی دیگر معتبر نیست.')
};
loginSubmit=async function(e){
 e.preventDefault();if(!state.portable&&!state.server){showServerRequiredMessage();return}
 const username=latinDigits($('#usernameInput')?.value||'').trim().toLowerCase(),pass=latinDigits($('#passwordInput').value).trim();$('#loginError').textContent='';
 if(!username){$('#loginError').textContent='نام کاربری را وارد کنید.';return}if(!pass){$('#loginError').textContent='رمز عبور را وارد کنید.';return}
 setLoginBusy(true,'در حال بررسی حساب کاربری…');
 try{const j=await appServices.login({username,password:pass});state.token=j.token;state.role='admin';org159SetIdentity(j.user);state.permissions=j.permissions||state.permissions;if(j.must_change)await completeRequiredPasswordChange();state.data=await appServices.bootstrap();hydrate(state.data);await enterApp()}
 catch(err){$('#loginError').textContent=String(err.message||err).replace(/^Error:\s*/,'')}
 finally{setLoginBusy(false)}
};
logout=function(){
 const token=state.token;if(token){appServices.logout().catch(()=>{})}
 state.token='';state.data=null;state.people=[];state.pageHistory=[];org159SetIdentity(null);$('#appShell').classList.add('hidden');showLogin()
};
retryServerConnection=async function(){setLoginBusy(true,'در حال بررسی مجدد اجرای برنامه…');$('#loginError').textContent='';try{state.runtimeReady=refreshRuntimeStatus();const status=await state.runtimeReady;if(status.portable||status.server){$('#passwordInput').disabled=false;$('#passwordSubmit').disabled=false;$('#openLocalServer').classList.add('hidden');if(!$('#passwordForm').classList.contains('hidden'))$('#loginDesc').textContent='نام کاربری و رمز شخصی خود را وارد کنید.'}else showServerRequiredMessage()}finally{setLoginBusy(false)}};
function org162UserGet(path){return state.portable?portableApi.get(path):api.get(path)}
function org162UserPost(path,body){return state.portable?portableApi.post(path,body):api.post(path,body)}
org159UserForm=function(user=null){
 const editing=!!user,isOwner=user?.role==='owner',permOptions=ORG421_ACCESS.formValues(user?.role||'admin',user?.permissions);
 const permissionBlock=isOwner?`<fieldset class="permission-fieldset"><legend>مجوزهای حساب</legend><p>حساب مدیر اصلی همیشه دسترسی کامل دارد و مجوزهای آن قابل کاهش نیست.</p></fieldset>`:`<fieldset class="permission-fieldset"><legend>مجوزهای کاربر مدیریتی</legend><div class="permission-grid">${permOptions.map(x=>`<label class="permission-option"><input type="checkbox" name="perm_${esc(x.key)}" ${x.checked?'checked':''}/><span><b>${esc(x.label)}</b><small>${esc(x.description)}</small></span></label>`).join('')}</div></fieldset>`;
 $('#personModalContent').innerHTML=`<form id="org159UserForm" class="user-form"><div class="modal-title"><h2>${editing?'ویرایش حساب کاربری':'افزودن کاربر مدیریتی'}</h2><p>${editing?'اطلاعات حساب و مجوزهای مدیریتی را تنظیم کنید.':'برای کاربر یک رمز موقت تصادفی ساخته می‌شود؛ نقش و مجوزها از Backend اعمال می‌شوند.'}</p></div><div class="form-grid"><label><span>نام و نام خانوادگی</span><input name="full_name" required value="${esc(user?.full_name||'')}"/></label><label><span>نام کاربری انگلیسی</span><input name="username" required dir="ltr" ${editing?'readonly':''} value="${esc(user?.username||'')}" placeholder="مثلاً ali.ahmadi"/></label><label><span>عنوان / سمت در سامانه</span><input name="title" required value="${esc(user?.title||'کاربر مدیریتی')}"/></label><label><span>شماره همراه</span><input name="phone" dir="ltr" inputmode="tel" value="${esc(user?.phone||'')}"/></label>${permissionBlock}</div><div class="profile-actions"><button class="secondary" type="button" id="org159CancelUser">انصراف</button><button class="primary" type="submit">${editing?'ذخیره تغییرات':'ایجاد حساب'}</button></div></form>`;
 $('#personModal').classList.remove('hidden');$('#org159CancelUser').onclick=()=>$('#personModal').classList.add('hidden');
 window.SazmanHRSecurityUI?.decorateUserForm?.($('#org159UserForm'),user);
 $('#org159UserForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),data=Object.fromEntries(fd.entries());data.permissions={};ORG421_ACCESS.delegable.forEach(k=>{data.permissions[k]=fd.has('perm_'+k);delete data['perm_'+k]});try{const result=await org162UserPost(editing?'/users/update':'/users/create',data);$('#personModal').classList.add('hidden');await renderUserManagement();if(result.temporary_password)org159TemporaryPasswordCard(result.user,result.temporary_password);else toast('حساب کاربری ذخیره شد',result.user.full_name)}catch(err){toast('ثبت حساب انجام نشد',err.message,'error')}}
};

org159ToggleUser=async function(user){if(user.role==='owner')return toast('مدیر اصلی همیشه فعال است','','error');const active=!user.active;if(!confirm(`حساب «${user.full_name}» ${active?'فعال':'غیرفعال'} شود؟`))return;try{await org162UserPost('/users/toggle',{username:user.username,active});await renderUserManagement();toast('وضعیت حساب تغییر کرد',user.full_name)}catch(e){toast('تغییر وضعیت انجام نشد',e.message,'error')}};
org159ResetUser=async function(user){if(!confirm(`رمز «${user.full_name}» بازنشانی شود؟ رمز قبلی بلافاصله نامعتبر خواهد شد.`))return;try{const result=await org162UserPost('/users/reset-password',{username:user.username});org159TemporaryPasswordCard(result.user,result.temporary_password);await renderUserManagement()}catch(e){toast('بازنشانی رمز انجام نشد',e.message,'error')}};
renderUserManagement=async function(){
 const host=$('#usersTable');if(!host||!state.isOwner)return;host.innerHTML='<div class="empty-state compact"><div class="loader"></div><p>در حال دریافت حساب‌ها…</p></div>';
 try{const users=await org162UserGet('/users'),active=users.filter(x=>x.active).length,admins=users.filter(x=>x.role==='admin').length,delegated=users.filter(x=>x.role==='admin'&&x.permissions?.backup_restore).length;$('#userKpis').innerHTML=`<article><span>کل حساب‌ها</span><strong>${fa(users.length)}</strong><small>مدیر اصلی و کاربران مدیریتی</small></article><article><span>حساب فعال</span><strong>${fa(active)}</strong><small>مجاز به ورود</small></article><article><span>کاربر مدیریتی</span><strong>${fa(admins)}</strong><small>${fa(delegated)} حساب با مجوز پشتیبان کامل</small></article>`;
 host.innerHTML=`<table><thead><tr><th>کاربر</th><th>نام کاربری</th><th>سطح دسترسی</th><th>وضعیت</th><th>آخرین ورود</th><th>عملیات</th></tr></thead><tbody>${users.map(u=>`<tr><td><button class="user-name-button" data-user-details="${esc(u.username)}"><i>${esc((u.full_name||'?').slice(0,1))}</i><span><b>${esc(u.full_name)}</b><small>${esc(u.title||'—')}</small></span></button></td><td dir="ltr">${esc(u.username)}</td><td><span class="user-role-chip ${u.role}">${esc(org159RoleLabel(u.role))}</span><small style="display:block;margin-top:5px;max-width:260px">${esc(ORG421_ACCESS.permissionSummary(u.role,u.permissions))}</small></td><td><span class="user-status-chip ${u.active?'active':'inactive'}">${u.active?'فعال':'غیرفعال'}</span></td><td>${esc(org159Date(u.last_login_at))}</td><td><div class="user-actions"><button data-user-edit="${esc(u.username)}" type="button">ویرایش</button>${u.role==='owner'?'':`<button data-user-reset="${esc(u.username)}" type="button">بازنشانی رمز</button><button data-user-toggle="${esc(u.username)}" type="button">${u.active?'غیرفعال‌سازی':'فعال‌سازی'}</button>`}</div></td></tr>`).join('')}</tbody></table>`;
 const map=new Map(users.map(x=>[x.username,x]));host.querySelectorAll('[data-user-details]').forEach(b=>b.onclick=()=>org159UserDetails(map.get(b.dataset.userDetails)));host.querySelectorAll('[data-user-edit]').forEach(b=>b.onclick=()=>org159UserForm(map.get(b.dataset.userEdit)));host.querySelectorAll('[data-user-reset]').forEach(b=>b.onclick=()=>org159ResetUser(map.get(b.dataset.userReset)));host.querySelectorAll('[data-user-toggle]').forEach(b=>b.onclick=()=>org159ToggleUser(map.get(b.dataset.userToggle)));
 }catch(e){host.innerHTML=`<div class="empty-state"><div>!</div><h3>فهرست کاربران دریافت نشد</h3><p>${esc(e.message)}</p></div>`}
};

recordLocalHistory=function(action,subject,details={}){
 const actor=state.currentUser?.full_name||state.currentUser?.username||'سامانه';const item={action,subject,details,changed_at:new Date().toISOString(),actor_name:actor,username:state.currentUser?.username||''};
 const h=JSON.parse(storage.getItem('sazmanhr_history')||'[]');h.unshift(item);storage.setItem('sazmanhr_history',JSON.stringify(h.slice(0,200)));state.history=h;
 if(state.portable&&state.token)portableApi.post('/history/add',item).catch(()=>{});
};
renderHistory=async function(){
 let rows=[];if(state.portable){try{rows=await portableApi.get('/history')}catch(e){}}else if(state.server){try{rows=await api.get('/history')}catch(e){}}else{try{rows=JSON.parse(storage.getItem('sazmanhr_history')||'[]')}catch(e){}}
 rows=rows.filter(x=>!(x.action==='ویرایش دستی'&&(x.subject||x.person_name)==='منوچهر تیموری'));state.history=rows;
 $('#historyList').innerHTML=rows.length?rows.map(x=>{const d=x.details||{},detail=Object.entries(d).slice(0,3).map(([k,v])=>`${k}: ${typeof v==='object'?JSON.stringify(v):v}`).join(' • ');return `<div class="timeline-item activity-item"><div class="timeline-icon">↻</div><div><h4>${esc(x.action||'فعالیت سامانه')}</h4><p>${esc(x.subject||'سامانه')}${detail?` — ${esc(detail)}`:''}</p><small>${esc(x.actor_name||x.username||'سامانه')}</small></div><time>${esc(org159Date(x.changed_at||x.time))}</time></div>`}).join(''):'<div class="panel empty-state"><div>↻</div><h3>هنوز فعالیتی ثبت نشده است</h3><p>پس از ورود یا انجام عملیات مدیریتی، سوابق با نام واقعی کاربر در این قسمت نمایش داده می‌شود.</p></div>'
};
window.addEventListener('load',()=>{const cp=$('#changePassword');if(cp)cp.onclick=async()=>{if(state.role!=='admin')return;const current=window.prompt('رمز فعلی را وارد کنید:');if(!current)return;const first=window.prompt('رمز جدید حداقل ۶ نویسه و بدون فاصله:');if(!first)return;const second=window.prompt('رمز جدید را دوباره وارد کنید:');const normalizedFirst=latinDigits(first).trim(),normalizedSecond=latinDigits(second).trim();if(normalizedFirst!==normalizedSecond)return toast('تکرار رمز یکسان نیست','','error');try{await appServices.changePassword(current,normalizedFirst);toast('رمز شخصی شما تغییر کرد')}catch(e){toast('تغییر رمز ناموفق',e.message,'error')}}});


/* ========================================================================
   v4.1.64 — resilient single-instance startup and graceful full shutdown.
   The portable launcher now reuses a running instance from this exact folder,
   selects another free localhost port when 8765 belongs to another program,
   serializes simultaneous double-clicks, and exposes an owner-only shutdown.
   ======================================================================== */
async function org163ShutdownApplication(){
 const btn=$('#shutdownAppBtn');
 if(!state.portable)return toast('این گزینه فقط در اجرای مستقل فعال است','سامانه را از فایل EXE اجرا کنید.','error');
 if(!state.isOwner)return toast('دسترسی کافی نیست','بستن کامل سامانه فقط برای مدیر اصلی مجاز است.','error');
 if(!confirm('سامانه به‌طور کامل بسته شود؟ پس از آن برای ورود دوباره باید فایل EXE را اجرا کنید.'))return;
 if(btn)btn.disabled=true;
 try{
  await portableApi.post('/shutdown',{});
  document.title='سامانه منابع انسانی بسته شد';
  document.body.innerHTML='<main class="org163-shutdown-screen" dir="rtl"><section><div>✓</div><h1>سامانه با موفقیت بسته شد</h1><p>اکنون می‌توانید این زبانه مرورگر را ببندید. برای اجرای دوباره، روی فایل «SazmanHR.exe» کلیک کنید.</p></section></main>';
  setTimeout(()=>{try{window.close()}catch(e){}},1000);
 }catch(e){if(btn)btn.disabled=false;toast('بستن کامل انجام نشد',e.message,'error')}
}
window.addEventListener('load',()=>{const b=$('#shutdownAppBtn');if(b)b.onclick=org163ShutdownApplication});
