  html=html.replace(/class="org69-approved-post org79-approved-post/, 'class="org69-approved-post org79-approved-post org180-guard-aggregate');
  if(!html.includes('org180-guard-note'))html=org180AppendInsideTitle(html,'<small class="org180-guard-note">نمایش یکپارچه نگهبان‌ها در کنار پست‌های بانام</small>');
